import subprocess, os, sys, textwrap, shlex, json, pathlib
def run(args, inp=None, env=None, timeout=5):
    e=dict(os.environ)
    if env: e.update(env)
    try:
        p=subprocess.run(["./executable"]+args, input=inp, capture_output=True, text=True, timeout=timeout, env=e)
        return p.stdout, p.stderr, p.returncode
    except subprocess.TimeoutExpired as ex:
        return (ex.stdout or b'').decode() if isinstance(ex.stdout, bytes) else (ex.stdout or ""), (ex.stderr or b'').decode() if isinstance(ex.stderr, bytes) else (ex.stderr or ""), "TIMEOUT"

for args in [["-H"], ["-m"], ["-m","-h"], ["-C"], ["-W","-N","-n"], ["-N","-n"], ["-x"], ["--unknown"], ["-V","extra"], ["-h","extra"]]:
    o,e,c=run(args)
    print(f"=== {args} exit={c} stdout_len={len(o)} stderr_len={len(e)}")
    print("STDOUT:", o[:3000])
    print("STDERR:", e[:3000])

PY
"}

