schema=open("/tmp/schema.txt").read()
def cols(fmt):
    m=re.search(rf"CREATE TABLE lnav_db\.{re.escape(fmt)}  \(\n(.*?)\n, PRIMARY KEY \(log_line\)\n\);", schema, re.S)
    if not m: return {}
    body=m.group(1)
    mm=re.search(r"-- BEGIN Format-specific fields:(.*?)-- END Format-specific fields", body, re.S)
    seg=mm.group(1) if mm else ""
    out={}
    for line in seg.splitlines():
        line=line.strip().rstrip(",")
        mm2=re.match(r'"?([^"\s]+)"?\s+([A-Z]+)', line)
        if mm2: out[mm2.group(1)]=mm2.group(2)
    return out
