#!/usr/bin/env python3
"""A reimplementation of the lnav log-file navigator (headless + TUI).

Written from scratch based on black-box observation of the reference
program's command-line, headless, management and interactive behaviour.
"""
import os, sys, re, json, math, time, datetime, subprocess, shlex, glob, io, csv, gzip, bz2, lzma, tarfile, zipfile, hashlib, random, struct, stat, fnmatch, itertools, traceback
from collections import OrderedDict, defaultdict

try:
    import lnav_data
    DATA = lnav_data.DATA
    def data_text(key):
        return lnav_data._text(key)
except Exception:
    DATA = {"formats": {}, "format_order": [], "format_desc": {}, "http_status": [], "known_columns": []}
    def data_text(key):
        return ""

VERSION = "lnav 0.14.0-8ad2d43"
VERSION_NUM = "0.14.0"

# ---------------------------------------------------------------------------
# small utilities

def _now_local():
    return datetime.datetime.now().astimezone()

def format_float(v):
    if math.isnan(v):
        return "nan"
    if math.isinf(v):
        return "inf" if v > 0 else "-inf"
    if v == int(v) and abs(v) < 1e15:
        return str(int(v))
    return repr(v)

def cell_display(v):
    """Convert an SQL value to its on-screen display string."""
    if v is None:
        return "<NULL>"
    if isinstance(v, bool):
        return "1" if v else "0"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return format_float(v)
    if isinstance(v, (bytes, bytearray)):
        s = bytes(v).decode("utf-8", "surrogateescape")
        return s
    s = str(v)
    return s

_CTRL_DISPLAY = {"\n": "␊", "\r": "␍", "\t": "⇥"}

def cell_display_clean(v):
    s = cell_display(v)
    for k, val in _CTRL_DISPLAY.items():
        s = s.replace(k, val)
    return s

def disp_width(s):
    import unicodedata
    w = 0
    for ch in s:
        if unicodedata.combining(ch):
            continue
        w += 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
    return w

def truncate_middle(s, width):
    if disp_width(s) <= width:
        return s
    if width <= 1:
        return "…"[:width]
    # keep first 60 and last (width-61) for the observed 120-column cap
    first = width // 2
    last = width - first - 1
    # take by characters (good enough for the common ASCII case)
    return s[:first] + "⋯" + (s[-last:] if last > 0 else "")

def pad_to_width(s, width, align="left"):
    dw = disp_width(s)
    if dw >= width:
        return s
    pad = width - dw
    if align == "right":
        return " " * pad + s
    if align == "center":
        left = pad // 2
        return " " * left + s + " " * (pad - left)
    return s + " " * pad

def quote_id(name):
    return '"' + str(name).replace('"', '""') + '"'

def md5_hex(data: bytes):
    return hashlib.md5(data).hexdigest()

# ---------------------------------------------------------------------------
# time parsing

_MONTHS = {"jan":1,"feb":2,"mar":3,"apr":4,"may":5,"jun":6,"jul":7,"aug":8,"sep":9,"oct":10,"nov":11,"dec":12}

class ParsedTime:
    __slots__ = ("dt", "has_year", "has_date", "epoch")
    def __init__(self, dt, has_year=True, has_date=True, epoch=None):
        self.dt = dt; self.has_year = has_year; self.has_date = has_date; self.epoch = epoch

def _tz_from_offset(sign, hh, mm):
    off = datetime.timedelta(hours=int(hh), minutes=int(mm))
    if sign == "-":
        off = -off
    return datetime.timezone(off)

_TZ_NAMES = {"UTC":0,"GMT":0,"Z":0,"UT":0}

def _convert_to_local(dt):
    """If dt is aware, convert to local time and drop the zone; else keep."""
    if dt.tzinfo is not None:
        try:
            local = dt.astimezone()
        except Exception:
            local = dt
        return local.replace(tzinfo=None)
    return dt

def _parse_with_format(fmt, s):
    """Parse s using an lnav/strftime-like format string. Returns ParsedTime or None."""
    s_stripped = s.strip()
    # epoch shortcuts used by a few formats
    if fmt in ("%s",):
        m = re.match(r'^(-?\d+(?:\.\d+)?)$', s_stripped)
        if not m:
            return None
        val = float(m.group(1))
        dt = datetime.datetime.fromtimestamp(val).replace(tzinfo=None) if False else datetime.datetime.fromtimestamp(val, datetime.timezone.utc).astimezone().replace(tzinfo=None)
        return ParsedTime(dt, True, True, val)
    if fmt in ("%6", "%9", "%3"):
        m = re.match(r'^(-?\d+)$', s_stripped)
        if not m:
            return None
        digits = int(fmt[1])
        val = int(m.group(1)) / (10 ** digits)
        dt = datetime.datetime.fromtimestamp(val, datetime.timezone.utc).astimezone().replace(tzinfo=None)
        return ParsedTime(dt, True, True, val)
    # Build a regex from the format
    i = 0
    regex = "^"
    fields = []
    while i < len(fmt):
        c = fmt[i]
        if c == "%" and i + 1 < len(fmt):
            tok = fmt[i+1]
            if tok == "%":
                regex += re.escape("%"); i += 2; continue
            if tok == "Y":
                regex += r"(?P<Y>\d{4})"; fields.append("Y")
            elif tok == "y":
                regex += r"(?P<y>\d{2})"; fields.append("y")
            elif tok == "m":
                regex += r"(?P<m>\d{1,2})"; fields.append("m")
            elif tok == "d":
                regex += r"(?P<d> ?\d{1,2})"; fields.append("d")
            elif tok == "e":
                regex += r"(?P<d> ?\d{1,2})"; fields.append("d")
            elif tok == "H":
                regex += r"(?P<H>\d{1,2})"; fields.append("H")
            elif tok == "I":
                regex += r"(?P<I>\d{1,2})"; fields.append("I")
            elif tok == "M":
                regex += r"(?P<M>\d{1,2})"; fields.append("M")
            elif tok == "S":
                regex += r"(?P<S>\d{1,2})"; fields.append("S")
            elif tok == "L":
                regex += r"(?P<L>\d{1,3})"; fields.append("L")
            elif tok == "f":
                regex += r"(?P<f>\d{1,6})"; fields.append("f")
            elif tok in ("3", "6", "9"):
                # fractional epoch digits following %s style handled above;
                # here treat as a fractional-second field with that many digits
                regex += r"(?P<frc>\d{%s})" % tok; fields.append("frc" + tok)
            elif tok == "s":
                regex += r"(?P<epoch>-?\d+(?:\.\d+)?)"; fields.append("epoch")
            elif tok == "b" or tok == "h":
                regex += r"(?P<b>[A-Za-z]{3,9})"; fields.append("b")
            elif tok == "B":
                regex += r"(?P<b>[A-Za-z]+)"; fields.append("b")
            elif tok == "a" or tok == "A":
                regex += r"(?:[A-Za-z]+)"; 
            elif tok == "p":
                regex += r"(?P<p>AM|PM|am|pm)"; fields.append("p")
            elif tok == "z":
                regex += r"(?P<z>Z|[+-]\d{2}:?\d{2})"; fields.append("z")
            elif tok == "Z":
                regex += r"(?P<Z>[A-Za-z]{1,5}(?:[+-]\d{2}:?\d{2})?)"; fields.append("Z")
            elif tok == "j":
                regex += r"(?P<j>\d{1,3})"; fields.append("j")
            else:
                regex += re.escape("%" + tok)
            i += 2
        else:
            regex += re.escape(c); i += 1
    regex += "$"
    try:
        m = re.match(regex, s_stripped)
    except re.error:
        return None
    if not m:
        return None
    g = m.groupdict()
    try:
        if g.get("epoch") is not None:
            val = float(g["epoch"])
            dt = datetime.datetime.fromtimestamp(val, datetime.timezone.utc).astimezone().replace(tzinfo=None)
            return ParsedTime(dt, True, True, val)
        has_year = g.get("Y") is not None or g.get("y") is not None
        if g.get("Y"):
            year = int(g["Y"])
        elif g.get("y"):
            yy = int(g["y"]); year = 2000 + yy if yy < 70 else 1900 + yy
        else:
            year = 1900
        has_date = (g.get("m") or g.get("b") or g.get("d") or g.get("j")) is not None
        month = 1; day = 1
        if g.get("b"):
            month = _MONTHS.get(g["b"][:3].lower(), 1)
        if g.get("m"):
            month = int(g["m"])
        if g.get("d"):
            day = int(g["d"])
        if g.get("j") and not g.get("d"):
            # day of year
            base = datetime.date(year, 1, 1) + datetime.timedelta(days=int(g["j"]) - 1)
            month, day = base.month, base.day
        hour = 0
        if g.get("H") is not None:
            hour = int(g["H"])
        elif g.get("I") is not None:
            hour = int(g["I"]) % 12
            if g.get("p") and g["p"].lower() == "pm":
                hour += 12
        minute = int(g.get("M") or 0)
        sec = int(g.get("S") or 0)
        micro = 0
        if g.get("L"):
            micro = int(g["L"].ljust(3, "0")) * 1000
        if g.get("f"):
            micro = int(g["f"].ljust(6, "0")[:6])
        if g.get("frc6"):
            micro = int(g["frc6"])
        dt = datetime.datetime(year, month, day, hour, minute, sec, micro)
        # timezone
        if g.get("z"):
            zv = g["z"]
            if zv == "Z":
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                mm = re.match(r'([+-])(\d{2}):?(\d{2})', zv)
                dt = dt.replace(tzinfo=_tz_from_offset(mm.group(1), mm.group(2), mm.group(3)))
            dt = _convert_to_local(dt)
        elif g.get("Z"):
            zv = g["Z"]
            mm = re.match(r'([A-Za-z]+)([+-])(\d{2}):?(\d{2})', zv)
            if mm:
                dt = dt.replace(tzinfo=_tz_from_offset(mm.group(2), mm.group(3), mm.group(4)))
                dt = _convert_to_local(dt)
            elif zv.upper() in _TZ_NAMES:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = _convert_to_local(dt)
        return ParsedTime(dt, has_year, has_date)
    except Exception:
        return None

_GENERIC_FORMATS = [
    "%Y-%m-%dT%H:%M:%S.%f%z", "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%dT%H:%M:%S",
    "%Y-%m-%d %H:%M:%S.%f%z", "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S%z", "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%d %H:%M", "%Y-%m-%d",
    "%Y/%m/%d %H:%M:%S", "%Y/%m/%d",
    "%d/%b/%Y:%H:%M:%S %z", "%d/%b/%Y:%H:%M:%S",
    "%m/%d/%Y %H:%M:%S", "%m/%d/%Y",
    "%d %b %Y %H:%M:%S.%L", "%d %b %Y %H:%M:%S", "%d %b %Y",
    "%b %d %Y %H:%M:%S", "%b %d %H:%M:%S.%L", "%b %d %H:%M:%S",
    "%a %b %d %H:%M:%S %Y", "%a, %d %b %Y %H:%M:%S %z",
    "%Y-%m-%dT%H:%M:%S.%L%z", "%Y-%m-%d %H:%M:%S,%L", "%Y-%m-%d %H:%M:%S.%L",
    "%H:%M:%S.%f", "%H:%M:%S.%L", "%H:%M:%S",
    "%b-%d %H:%M:%S", "%m-%d %H:%M:%S.%L", "%m-%d %H:%M:%S",
]

def parse_timestamp(s, fmt_list=None):
    """Parse a timestamp string; returns ParsedTime or None."""
    if s is None:
        return None
    if isinstance(s, (int, float)):
        val = float(s)
        # heuristics: nanoseconds / microseconds / millis / seconds
        av = abs(val)
        if av > 1e17:
            val = val / 1e9
        elif av > 1e14:
            val = val / 1e6
        elif av > 1e11:
            val = val / 1e3
        try:
            dt = datetime.datetime.fromtimestamp(val, datetime.timezone.utc).astimezone().replace(tzinfo=None)
        except Exception:
            return None
        return ParsedTime(dt, True, True, val)
    s = str(s).strip()
    if not s:
        return None
    if fmt_list:
        for fmt in fmt_list:
            if isinstance(fmt, (list, tuple)):
                continue
            pt = _parse_with_format(fmt, s)
            if pt:
                return pt
    # numeric epoch string
    if re.match(r'^-?\d{10,}(?:\.\d+)?$', s):
        return parse_timestamp(float(s))
    # ISO with Z / comma fractional etc -- normalize a little for candidates
    candidates = [s]
    if s.endswith("Z") and "T" in s:
        candidates.append(s[:-1] + "+0000")
    for cand in candidates:
        for fmt in _GENERIC_FORMATS:
            pt = _parse_with_format(fmt, cand)
            if pt:
                return pt
    # try python fromisoformat
    try:
        iso = s.replace("Z", "+00:00")
        dt = datetime.datetime.fromisoformat(iso)
        return ParsedTime(_convert_to_local(dt), True, True)
    except Exception:
        pass
    # RFC-like: ignore weekday prefix
    m = re.match(r'^[A-Za-z]{3,9},?\s+(.*)$', s)
    if m:
        return parse_timestamp(m.group(1), fmt_list)
    return None

def fmt_log_time(dt):
    if dt is None:
        return None
    return dt.strftime("%Y-%m-%d %H:%M:%S.") + ("%06d" % dt.microsecond)

def dt_to_msecs(dt):
    if dt is None:
        return None
    try:
        return int(round(dt.replace(tzinfo=datetime.timezone.utc).timestamp() * 1000)) if False else int(round(time.mktime(dt.timetuple()) * 1000)) + dt.microsecond // 1000
    except Exception:
        return None

# ---------------------------------------------------------------------------
# levels

LEVELS = ["trace", "debug", "info", "stats", "notice", "warning", "error", "critical", "fatal", "unknown", "invalid"]
_LEVEL_SYNONYMS = {
    "trace": "trace", "trc": "trace",
    "debug": "debug", "dbg": "debug", "verbose": "debug",
    "info": "info", "information": "info", "informational": "info",
    "stats": "stats", "stat": "stats",
    "notice": "notice", "notification": "notice", "note": "notice",
    "warning": "warning", "warn": "warning",
    "error": "error", "err": "error", "severe": "error",
    "critical": "critical", "crit": "critical",
    "fatal": "fatal", "emerg": "fatal", "emergency": "fatal", "alert": "fatal",
    "unknown": "unknown",
}

def normalize_level_name(raw):
    if raw is None:
        return "unknown"
    if isinstance(raw, (int, float)):
        return "unknown"
    s = str(raw).strip().strip("[]()").strip().lower()
    if s in _LEVEL_SYNONYMS:
        return _LEVEL_SYNONYMS[s]
    # prefixes like "warning:" etc
    for key in sorted(_LEVEL_SYNONYMS, key=len, reverse=True):
        if s.startswith(key):
            return _LEVEL_SYNONYMS[key]
    return s if s in LEVELS else "unknown" if not s else s

def level_from_map(raw, level_map):
    """level_map as defined in a format; keys are level names, values int/str patterns."""
    if raw is None:
        return None
    raw_s = str(raw)
    for lvl, pat in level_map.items():
        name = normalize_level_name(lvl)
        if isinstance(pat, bool):
            continue
        if isinstance(pat, (int, float)):
            try:
                if float(raw_s) == float(pat):
                    return name
            except Exception:
                pass
        elif isinstance(pat, str):
            # numeric string in map?
            if pat == raw_s:
                return name
            try:
                adj = translate_regex(pat)
                if re.search(adj, raw_s):
                    return name
            except Exception:
                pass
    return None

# ---------------------------------------------------------------------------
# regex translation (PCRE-ish -> python re)

def translate_regex(pattern):
    if pattern is None:
        return pattern
    p = pattern
    # named groups (?<name> -> (?P<name>  (not lookbehind)
    p = re.sub(r'\(\?<([A-Za-z_])', r'(?P<\1', p)
    # backrefs \k<name> -> (?P=name)
    p = re.sub(r'\\k<([A-Za-z_]\w*)>', r'(?P=\1)', p)
    # atomic groups (?> -> (?:
    p = p.replace("(?>", "(?:")
    # possessive quantifiers ++ *+ ?+ }+ -> plain
    p = re.sub(r'([*+?}])\+', r'\1', p)
    return p

def compile_pattern(pattern):
    try:
        return re.compile(translate_regex(pattern))
    except re.error:
        # try stripping inline flag placement issues
        p = translate_regex(pattern)
        p = p.replace("(?i)", "")
        flags = re.IGNORECASE if "(?i" in pattern else 0
        return re.compile(p, flags)

PYEOF
wc -l /workspace/src/__main__.py
