        if g.get("m"):
            month = int(g["m"])
        if g.get("d"):
            day = int(g["d"])
        if g.get("j") and not g.get("d"):
            # day of year
            base = datetime.date(year, 1, 1) + datetime.timedelta(days=int(g["j"]) - 1)
            month, day = base.month, base.day
        hour = 0
        if g.get("H") is not None:
            hour = int(g["H"])
        elif g.get("I") is not None:
            hour = int(g["I"]) % 12
            if g.get("p") and g["p"].lower() == "pm":
                hour += 12
        minute = int(g.get("M") or 0)
        sec = int(g.get("S") or 0)
        micro = 0
        if g.get("L"):
            micro = int(g["L"].ljust(3, "0")) * 1000
        if g.get("f"):
