# levels

LEVELS = ["trace", "debug", "info", "stats", "notice", "warning", "error", "critical", "fatal", "unknown", "invalid"]
_LEVEL_SYNONYMS = {
    "trace": "trace", "trc": "trace",
    "debug": "debug", "dbg": "debug", "verbose": "debug",
    "info": "info", "information": "info", "informational": "info",
    "stats": "stats", "stat": "stats",
    "notice": "notice", "notification": "notice", "note": "notice",
    "warning": "warning", "warn": "warning",
    "error": "error", "err": "error", "severe": "error",
    "critical": "critical", "crit": "critical",
    "fatal": "fatal", "emerg": "fatal", "emergency": "fatal", "alert": "fatal",
    "unknown": "unknown",
}

def normalize_level_name(raw):
    if raw is None:
        return "unknown"
    if isinstance(raw, (int, float)):
        return "unknown"
    s = str(raw).strip().strip("[]()").strip().lower()
    if s in _LEVEL_SYNONYMS:
        return _LEVEL_SYNONYMS[s]
    # prefixes like "warning:" etc
    for key in sorted(_LEVEL_SYNONYMS, key=len, reverse=True):
        if s.startswith(key):
            return _LEVEL_SYNONYMS[key]
    return s if s in LEVELS else "unknown" if not s else s

def level_from_map(raw, level_map):
    """level_map as defined in a format; keys are level names, values int/str patterns."""
    if raw is None:
        return None
    raw_s = str(raw)
    for lvl, pat in level_map.items():
        name = normalize_level_name(lvl)
        if isinstance(pat, bool):
            continue
        if isinstance(pat, (int, float)):
            try:
                if float(raw_s) == float(pat):
                    return name
            except Exception:
                pass
        elif isinstance(pat, str):
            # numeric string in map?
            if pat == raw_s:
                return name
            try:
                adj = translate_regex(pat)
                if re.search(adj, raw_s):
                    return name
            except Exception:
                pass
    return None

# ---------------------------------------------------------------------------
# regex translation (PCRE-ish -> python re)

def translate_regex(pattern):
    if pattern is None:
        return pattern
    p = pattern
    # named groups (?<name> -> (?P<name>  (not lookbehind)
    p = re.sub(r'\(\?<([A-Za-z_])', r'(?P<\1', p)
    # backrefs \k<name> -> (?P=name)
    p = re.sub(r'\\k<([A-Za-z_]\w*)>', r'(?P=\1)', p)
    # atomic groups (?> -> (?:
    p = p.replace("(?>", "(?:")
    # possessive quantifiers ++ *+ ?+ }+ -> plain
    p = re.sub(r'([*+?}])\+', r'\1', p)
    return p

def compile_pattern(pattern):
    try:
        return re.compile(translate_regex(pattern))
    except re.error:
        # try stripping inline flag placement issues
        p = translate_regex(pattern)
        p = p.replace("(?i)", "")
        flags = re.IGNORECASE if "(?i" in pattern else 0
        return re.compile(p, flags)

