        self.timestamp_format = self.defn.get("timestamp-format")
        if isinstance(self.timestamp_format, str):
            self.timestamp_format = [self.timestamp_format]
        self.multiline = self.defn.get("multiline", True)
        self.line_format = self.defn.get("line-format")
        self.hide_extra = self.defn.get("hide-extra", False)
        self.ts_divisor = self.defn.get("timestamp-divisor")
