    def _compute_columns(self):
        # returns list of (name, type)
        cols = []
        seen = set()
        if self.is_json:
            for k, v in self.values.items():
                if k == self.timestamp_field or k == self.body_field:
                    continue
                kind = (v or {}).get("kind", "string") if isinstance(v, dict) else "string"
                cols.append((k, _KIND_TYPE.get(kind, "TEXT")))
