                    v = self.values.get(cap) or {}
                    kind = v.get("kind", "string") if isinstance(v, dict) else "string"
                    cols.append((cap, _KIND_TYPE.get(kind, "TEXT")))
                    seen.add(cap)
        if not cols:
            # formats without value definitions: use captured names
            for pname in sorted([p[0] for p in self.patterns]):
                for (pn, comp, rw) in self.patterns:
                    if pn != pname: continue
                    caps = set(re.findall(r'\(\?<([A-Za-z_][\w-]*)>', rw))
                    for cap in sorted(caps):
                        if cap not in ("timestamp", "body", "level", "timestamp_f") and cap not in seen:
