class FormatRegistry:
    def __init__(self):
        self.formats = OrderedDict()  # name -> FormatDef
        self.sources = defaultdict(list)  # name -> [paths]
        prio = 0
        for name in DATA.get("format_order", []):
            defn = DATA.get("formats", {}).get(name)
            if defn is not None:
                self.formats[name] = FormatDef(name, defn, None, True, prio); prio += 1
        for name, defn in DATA.get("formats", {}).items():
            if name not in self.formats:
                self.formats[name] = FormatDef(name, defn, None, True, prio); prio += 1

    def load_custom_dir(self, base, errors):
        """Load format JSON files found under <base>/formats (recursively)."""
        if not base or not os.path.isdir(base):
            return
        fdir = os.path.join(base, "formats")
        if not os.path.isdir(fdir):
            return
        for root, dirs, files in os.walk(fdir):
            dirs.sort()
            for fn in sorted(files):
                if fn.endswith(".json") and not fn.endswith(".json.sample"):
                    self.load_custom_file(os.path.join(root, fn), errors)

    def load_custom_file(self, path, errors):
        try:
            with open(path, "r", encoding="utf-8", errors="surrogateescape") as fh:
                text = fh.read()
            d = json.loads(text)
        except Exception as e:
            return
        if not isinstance(d, dict):
            return
        for name, defn in d.items():
            if name == "$schema" or not isinstance(defn, dict):
                continue
            fd = FormatDef(name, defn, path, False, 1000 + len(self.formats))
            self.formats[name] = fd
            self.sources[name].append(path)

_FORMATS = None

def get_registry(include_dirs, home_dir, err_collector=None):
    global _FORMATS
    # A fresh registry is built per process anyway; include-dirs differ per run
    reg = FormatRegistry()
    errs = err_collector if err_collector is not None else []
    # system dirs
    for d in ["/etc/lnav", "/usr/etc/lnav"]:
        reg.load_custom_dir(d, errs)
        # also files directly in dir
    if home_dir:
        reg.load_custom_dir(home_dir, errs)
    for d in (include_dirs or []):
        reg.load_custom_dir(d, errs)
    return reg

