        if isinstance(value, bool):
            return 1 if value else 0
        if isinstance(value, (int, float)):
            return int(value)
        s = str(value).strip()
        try:
            return int(float(s)) if (("." in s) or ("e" in s.lower())) else int(s)
        except Exception:
            return 0
    if kind == "float":
        if isinstance(value, (int, float)):
            return float(value)
