def flatten_json(obj):
    """Flatten a JSON object to path -> value, using '/' separators and '#' for arrays."""
    out = OrderedDict()
    def rec(value, path):
        if isinstance(value, dict):
            out[path] = value
            for k, v in value.items():
                rec(v, path + "/" + str(k) if path else str(k))
        elif isinstance(value, list):
            out[path] = value
            out[path + "#"] = value
            for idx, v in enumerate(value):
                # sub-fields of the first element are accessible via '#'
                if idx == 0:
                    if isinstance(v, dict):
                        for k, vv in v.items():
                            rec(vv, path + "#/" + str(k))
                    else:
                        out[path + "#"] = v
                rec(v, path + "/" + str(idx))
        else:
            out[path] = value
