            continue
        if fields is None:
            continue
        vals = shlex.split(line) if line else []
        msg = Message()
        msg.format_name = "w3c_log"; msg.pattern_name = "std"
        msg.file = loaded; msg.line_no = idx; msg.end_line_no = idx
        msg.raw_lines = [line]
        msg.display = line
        fmap = {}
        for fname, val in zip(fields, vals):
            cname = fname.replace("-", "_")
            fmap[cname] = val
        # timestamp from date+time or datetime
        ts = None
        if "date" in fmap and "time" in fmap:
            pt = parse_timestamp(fmap["date"] + " " + fmap["time"])
            ts = pt.dt if pt else None
        elif "datetime" in fmap:
            pt = parse_timestamp(fmap["datetime"])
