            if cname in fmap:
                kind = "integer" if type_map.get(cname) == "INTEGER" else "string"
                msg.fields[cname] = convert_kind(fmap[cname], kind)
            else:
                msg.fields[cname] = None
        if "sc_status" in msg.fields and msg.fields["sc_status"] is not None:
            msg.level = "error" if not str(msg.fields["sc_status"]).startswith(("1", "2", "3")) else "info"
        else:
            msg.level = "info"
        msg.body = None
        messages.append(msg)
    return messages

def parse_bro_file(loaded, lines):
    fields = None; types = None; path_name = "conn"; sep = "\t"
    messages = []
    for idx, line in enumerate(lines):
        if line.startswith("#"):
            parts = line[1:].split("\t") if "\t" in line else line[1:].split()
            if parts:
                tag = parts[0]
                if tag == "fields":
                    fields = parts[1:]
                elif tag == "types":
                    types = parts[1:]
                elif tag == "path" and len(parts) > 1:
                    path_name = parts[1]
            if messages:
                # trailing headers act as continuation of the previous message
                messages[-1].raw_lines.append(line)
                messages[-1].display = "\n".join(messages[-1].raw_lines)
                if messages[-1].body:
                    messages[-1].body += "\n" + line
            continue
        if not fields:
            continue
        vals = line.split(sep)
        fmtname = "bro_%s_log" % path_name
        msg = Message()
        msg.format_name = fmtname; msg.pattern_name = "std"
        msg.file = loaded; msg.line_no = idx; msg.end_line_no = idx
        msg.raw_lines = [line]
        flds = {}
        disp_vals = []
        for i, fname in enumerate(fields):
            v = vals[i] if i < len(vals) else None
            cname = "bro_" + fname.replace(".", "_").replace("-", "_")
            tname = types[i] if types and i < len(types) else "string"
            if tname in ("port", "count"):
                kind = "integer"
            elif tname in ("interval", "double"):
                kind = "float"
            else:
                kind = "string"
            flds[cname] = convert_kind(v, kind) if v is not None else None
            if fname == "ts":
                disp_vals.append(fmt_log_time(parse_timestamp(float(v)).dt) if v else "")
            else:
                disp_vals.append(v if v is not None else "")
        msg.fields = flds
        pt = None
        if "bro_ts" in flds and flds["bro_ts"]:
            try:
                pt = parse_timestamp(float(flds["bro_ts"]))
            except Exception:
                pt = None
        msg.timestamp = pt.dt if pt else None; msg.actual_timestamp = msg.timestamp
        msg.level = "info"
        msg.display = "\t".join(disp_vals)
        msg.body = "\t".join(vals)
        loaded._bro_fields = fields; loaded._bro_types = types; loaded._bro_path = path_name
        messages.append(msg)
    return messages

