    else:
        # fall back to a dotlnav under HOME if HOME names a dir-like path that
        # exists, otherwise the current directory (matches observed fallback)
        if home and os.path.exists(os.path.dirname(home) or "."):
            # HOME was set but the directory itself does not exist: use cwd
