    work_dir = os.path.join(tmpdir, "lnav-user-%d-work" % os.getuid())
    return bin_path, dotlnav, work_dir

def _deep_merge(dst, src):
    for k, v in src.items():
        if k in dst and isinstance(dst[k], dict) and isinstance(v, dict):
            _deep_merge(dst[k], v)
        else:
            dst[k] = v
    return dst

def _json_pretty(value, indent=4, level=0):
    sp = " " * (indent * level)
    sp1 = " " * (indent * (level + 1))
    if isinstance(value, dict):
        if not value:
            return "{\n\n" + sp + "}"
        items = []
        for k, v in value.items():
            items.append(sp1 + json.dumps(str(k), ensure_ascii=False) + ": " + _json_pretty(v, indent, level + 1))
        return "{\n" + ",\n".join(items) + "\n" + sp + "}"
    if isinstance(value, list):
        if not value:
            return "[\n\n" + sp + "]"
        items = [sp1 + _json_pretty(v, indent, level + 1) for v in value]
        return "[\n" + ",\n".join(items) + "\n" + sp + "]"
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "null"
    if isinstance(value, float):
        return format_float(value)
