    def _decode_and_parse(self, lf):
        raw = lf.raw_bytes
        # mime/binary detection first
        is_binary = (b"\x00" in raw[:8192])
        text = None
        if not is_binary:
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                # try with errors replaced; if too many bad bytes treat as binary
                bad = 0
                try:
                    raw.decode("utf-8")
                except UnicodeDecodeError as e:
                    bad = 1
                if bad:
                    is_binary = (raw.count(b"\xff") > 0 and b"\x00" in raw) or _binary_ratio(raw) > 0.3
                    text = raw.decode("utf-8", "surrogateescape")
        if text is None:
            text = raw.decode("utf-8", "surrogateescape")
        lines = text.split("\n")
        if lines and lines[-1] == "":
            lines = lines[:-1]
        lines = [ln[:-1] if ln.endswith("\r") else ln for ln in lines]
        lf.lines = lines
        lf.is_binary = is_binary
        detect_and_parse(lf, self.registry)
        if lf.format_name:
            lf.mimetype = "text/log"
            if lf.format_name == "bro" or (lf.format_name or "").startswith("bro_"):
                lf.mimetype = "text/log"
        else:
            lf.mimetype = _guess_mimetype(lf, raw, is_binary)
        if lf.format_name:
            self.session_files.append(lf.display_path)

    def rebuild_messages(self):
        all_msgs = []
        for lf in self.files:
            for m in lf.messages:
                m.file = lf
                all_msgs.append(m)
        # sort by (time, file line no, path)
        def sort_key(m):
            return (m.timestamp or datetime.datetime.min, m.line_no, m.file.display_path if m.file else "")
        all_msgs.sort(key=sort_key)
        prev = None
        for i, m in enumerate(all_msgs):
            m.global_index = i
            if prev is not None and m.timestamp is not None and prev.timestamp is not None:
                m.idle_msecs = int(round((m.timestamp - prev.timestamp).total_seconds() * 1000))
            else:
