def _binary_ratio(raw):
    if not raw:
        return 0.0
    bad = sum(1 for b in raw[:8192] if b < 9 or (13 < b < 32))
    return bad / max(1, min(len(raw), 8192))

def _guess_mimetype(lf, raw, is_binary):
    if not raw:
        return "application/octet-stream"
    if is_binary:
        return "application/octet-stream"
    txt = raw[:4096]
    stripped = txt.strip()
    if stripped.startswith(b"#!"):
        first = stripped.split(b"\n", 1)[0].decode("utf-8", "replace")
        if "python" in first:
            return "text/x-python"
        if "sh" in first or "bash" in first:
            return "text/x-shellscript"
        return "text/plain"
    # a whole-file JSON document (not log lines)?
    if lf.display_path.endswith(".json"):
        try:
            json.loads(raw.decode("utf-8"))
            return "application/json"
        except Exception:
            pass
    if stripped.startswith(b"<") :
        return "text/xml"
    return "text/plain"

# archive / decompression ----------------------------------------------------

_ARCHIVE_EXTS = (".zip", ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz")

def _read_member_bytes(path):
    """Return (is_archive, [(inner_name, bytes), ...]) for an archive file."""
    low = path.lower()
    try:
        if low.endswith(".zip"):
            with zipfile.ZipFile(path) as z:
                out = []
                for info in z.infolist():
                    if info.is_dir():
                        continue
                    out.append((info.filename, z.read(info.filename)))
                return True, out
        if low.endswith((".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz")):
            with tarfile.open(path) as t:
                out = []
                for member in t.getmembers():
                    if member.isfile():
                        fh = t.extractfile(member)
                        out.append((member.name, fh.read() if fh else b""))
                return True, out
    except Exception:
        return False, []
    return False, []

def _decompress_single(path):
    low = path.lower()
    try:
        if low.endswith(".gz") and not low.endswith(".tar.gz"):
            with gzip.open(path, "rb") as fh:
                return fh.read()
        if low.endswith(".bz2"):
            with bz2.open(path, "rb") as fh:
                return fh.read()
        if low.endswith((".xz", ".lzma")):
            with lzma.open(path, "rb") as fh:
                return fh.read()
        if low.endswith(".zst"):
            # try external zstd if available
            p = subprocess.run(["zstd", "-dc", path], capture_output=True)
            if p.returncode == 0:
                return p.stdout
    except Exception:
        return None
    return None

