LEVEL_RANK = {"unknown": 0, "trace": 1, "debug": 2, "info": 3, "stats": 4, "notice": 5, "warning": 6, "error": 7, "critical": 8, "fatal": 9, "invalid": 10}

def filtered_messages(app, view_name="log"):
    msgs = app.messages
    out = []
    do_filter = app.views.get("log", {}).get("filtering", True) if view_name == "log" else True
    for m in msgs:
        if m.file is not None and not m.file.visible:
            continue
        if not do_filter or not app.filtering_enabled:
            out.append(m); continue
        if app.min_level:
            if LEVEL_RANK.get(m.level, 0) < LEVEL_RANK.get(app.min_level, 0):
                continue
        if app.hide_before and m.timestamp and m.timestamp < app.hide_before:
            continue
        if app.hide_after and m.timestamp and m.timestamp > app.hide_after:
            continue
        if app.hide_unmarked and not m.mark:
            continue
        keep = True
        for f in app.filters:
            if not f.get("enabled", True):
                continue
            pat = f.get("pattern", "")
            lang = f.get("language", "regex")
            text = m.log_text if m.log_text else ""
            if lang == "regex":
                try:
                    matched = re.search(translate_regex(pat), text) is not None
                except Exception:
                    matched = False
            else:
                matched = _eval_sql_expr(app, f.get("pattern", ""), m)
            if f.get("type") == "in" and not matched:
                keep = False; break
            if f.get("type") == "out" and matched:
                keep = False; break
        if not keep:
            continue
        if app.filter_expr:
            if not _eval_sql_expr(app, app.filter_expr, m):
                continue
        out.append(m)
    return out

def _eval_sql_expr(app, expr, msg):
    try:
        conn = app.ensure_db()
        upaths = unique_paths(app.files)
        row = message_row(app, msg, msg.format_name, upaths) if False else None
        # build param dict from all_logs row + format fields
        params = {}
        # use format table columns of the message's format
        r = message_row(app, msg, "all_logs", upaths)
        params.update(r)
        if msg.file and msg.file.format_def:
            r2 = message_row(app, msg, msg.format_name, upaths)
            params.update(r2)
        # sqlite named params are referenced as :name
        cur = conn.execute("SELECT CASE WHEN (%s) THEN 1 ELSE 0 END" % expr, params)
        val = cur.fetchone()
        return bool(val and val[0])
    except Exception:
        return False

def message_display_lines(app, msg):
    lf = msg.file
    if lf is not None and lf.format_def is not None and lf.format_def.is_json:
        lines = [msg.display] + list(msg.extra_display)
        return lines
    if lf is not None and lf.format_name == "logfmt_log":
        return [msg.display]
    if lf is not None and (lf.format_name == "w3c_log"):
        return [msg.display]
    return list(msg.raw_lines) if msg.raw_lines else [msg.display]

def _metadata_lines(msg):
    items = []
    if msg.comment:
        items.append(msg.comment)
    if msg.tags:
        try:
            tags = json.loads(msg.tags)
            if isinstance(tags, list):
                items.append(" ".join(str(t) for t in tags))
            else:
                items.append(str(msg.tags))
        except Exception:
            items.append(str(msg.tags))
    if msg.annotations:
        try:
            ann = json.loads(msg.annotations)
            if isinstance(ann, dict):
                for k, v in ann.items():
                    items.append(str(v))
            else:
                items.append(str(msg.annotations))
        except Exception:
            items.append(str(msg.annotations))
    if not items:
        return []
    lines = ["▌ Line %d metadata" % msg.global_index]
    for i, it in enumerate(items):
        branch = " └ " if i == len(items) - 1 else " ├ "
        lines.append(branch + str(it))
    return lines

def view_lines(app, name):
    """Returns a list of text lines for a view (headless rendering)."""
    if name == "log":
        msgs = filtered_messages(app)
        lines = []
        for m in msgs:
            lines.extend(message_display_lines(app, m))
            lines.extend(_metadata_lines(m))
        return lines
    if name == "text":
        lf = app.current_text_file
        if lf is None:
            return []
        if getattr(lf, "is_binary", False):
            return _hexdump_lines(lf)
        return list(lf.lines)
    if name == "help":
        return data_text("help_b64").split("\n")
    if name == "schema":
        return schema_text(app).split("\n")
    if name == "db":
        if app.db_result is None:
            return []
        return format_table_lines(app.db_result[0], app.db_result[1]).splitlines() if app.db_result[1] else []
    if name == "histogram":
        return _histogram_lines(app)
    if name == "pretty":
        return _pretty_lines(app)
    if name == "spectro":
        return _spectro_lines(app)
    if name == "timeline":
        return _timeline_lines(app)
    return []

def view_lines_from_top(app, name):
    lines = view_lines(app, name)
    v = app.views.get(name, {})
    top = v.get("top", 0) or 0
    if name == "log":
        # top is a log_line (message index); translate it to a display row
        msgs = filtered_messages(app)
        row = 0
        for m in msgs:
            if m.global_index >= top:
                break
            row += len(message_display_lines(app, m)) + len(_metadata_lines(m))
        else:
            # if top beyond all, start at the last message
            if msgs and top > msgs[-1].global_index:
                row = 0
                for m in msgs[:-1]:
                    row += len(message_display_lines(app, m)) + len(_metadata_lines(m))
        return lines[row:]
    return lines[top:]

def _hexdump_lines(lf):
    data = lf.raw_bytes or b""
    lines = []
    lines.append("     File Offset  00 01 02 03 04 05 06 07  08 09 0a 0b 0c 0d 0e 0f        ASCII      ")
    for off in range(0, len(data), 16):
        chunk = data[off:off + 16]
        hexs = []
        ascii_part = []
        for i in range(16):
            if i < len(chunk):
                b = chunk[i]
                hexs.append("%02x" % b)
                if b == 10:
                    ascii_part.append("_")
                elif 32 <= b < 127:
                    ascii_part.append(chr(b))
                elif b == 0:
                    ascii_part.append("⋄")
                elif b < 32:
                    ascii_part.append("•")
                else:
                    ascii_part.append("×")
            else:
                hexs.append("  ")
                ascii_part.append(" ")
        hexstr = " ".join(hexs[:8]) + "  " + " ".join(hexs[8:])
        lines.append("%16d  %s  %s" % (off, hexstr, "".join(ascii_part).rstrip()))
    return lines

def _histogram_buckets(app):
    msgs = [m for m in app.messages if m.timestamp is not None]
    if not msgs:
        return []
    size = app.hist_zoom_seconds or 3600
    buckets = {}
    for m in msgs:
        epoch = int(m.timestamp.replace(tzinfo=datetime.timezone.utc).timestamp()) if False else int(time.mktime(m.timestamp.timetuple()))
        start = epoch - (epoch % size)
        b = buckets.setdefault(start, [0, 0, 0, 0])  # total, errors, warnings, marks
        b[0] += 1
        if m.level == "error":
            b[1] += 1
        elif m.level == "warning":
            b[2] += 1
        if m.mark:
            b[3] += 1
    out = []
    for start in sorted(buckets):
        out.append((start, buckets[start]))
    return out

def _histogram_lines(app):
    lines = []
    for start, (total, errors, warnings, marks) in _histogram_buckets(app):
        dt = datetime.datetime.fromtimestamp(start)
        normal = total - errors - warnings
        lines.append(" %s %10d normal %10d errors %10d warnings %10d marks" % (dt.strftime("%a %b %d %H:%M:%S %Y"), normal, errors, warnings, marks))
        # The reference format uses fixed-ish padding; reformat to match the
        # observed layout (counts right-aligned in a wide field).
    # Rebuild in the observed style:
    lines = []
    for start, (total, errors, warnings, marks) in _histogram_buckets(app):
        dt = datetime.datetime.fromtimestamp(start)
        normal = total - errors - warnings
        lines.append(" %s %10d normal %10d errors %10d warnings %10d marks" % (dt.strftime("%a %b %d %H:%M:%S %Y"), normal, errors, warnings, marks))
    return lines

def _pretty_lines(app):
    msg = app._focused_message() if hasattr(app, "_focused_message") else None
    if app.current_view_name == "pretty" or True:
        pass
    # pretty-print the focused message / top text line
    if app.messages:
        m = app._focused_message()
        if m is None:
            return []
        text = m.log_text
        stripped = text.strip()
        if stripped.startswith("{") or stripped.startswith("["):
            try:
                obj = json.loads(stripped)
                return _json_pretty(obj).split("\n")
            except Exception:
                pass
        return [text]
    lf = app.current_text_file
    if lf:
        content = "\n".join(lf.lines)
        stripped = content.strip()
        if stripped.startswith("{") or stripped.startswith("["):
            try:
                obj = json.loads(stripped)
                return _json_pretty(obj).split("\n")
            except Exception:
                pass
        return ["".join(lf.lines)]
    return []

def _spectro_lines(app):
    return []

def _timeline_lines(app):
    # OPID timeline approximation
    msgs = app.messages
    if not msgs:
        return []
    lines = []
    lines.append("   Duration   | ✘▲ | Item         |")
    for m in msgs:
        op = _msg_opid(app, m) or ""
        lines.append("         0s000  ▂      %s %s" % ((m.file.display_path if m.file else ""), op))
    return lines

