        th = [(c[0], c[1], 1, 0) for c in STANDARD_HIDDEN]
        return std_start + extra + tail_visible + th
    # generic fallback: use sqlite's own pragma
    conn = app.db_conn
    if conn is not None:
        try:
            cur = conn.execute("SELECT name FROM sqlite_master WHERE name=?", (tname,))
            if cur.fetchone():
