class CommandError(Exception):
    """An error that should be reported to stderr in lnav style (exit stays 0 in headless)."""
    def __init__(self, text):
        super().__init__(text)
        self.text = text

def err_block(first_line, extra_lines=None):
    out = "  error: %s\n" % first_line
    for ln in (extra_lines or []):
        out += ln + "\n"
    return out

def snippet_block(source_label, content, caret=None, caret_msg=None):
    content_line = content
    out = " --> %s\n" % source_label
    out += " | %s\n" % (content_line.ljust(40) if len(content_line) < 40 else content_line)
    if caret is not None:
        out += " | %s%s" % (" " * caret, "^")
        if caret_msg:
            out += " " + caret_msg
        out += "\n"
    return out

def help_block_for_command(cmds_help, name):
    info = cmds_help.get(name)
    if info is None:
        return ""
    sig, desc_lines = info
    out = " = help: %s\n" % sig
    out += "         " + "═" * 70 + "\n"
    for ln in desc_lines:
        out += "           %s\n" % ln
    return out

# ---------------------------------------------------------------------------
# SQL command execution on App

def _split_sql_statements(sql):
    statements = []
    buf = ""
    i = 0
    import sqlite3 as _sq
    while i < len(sql):
        ch = sql[i]
        buf += ch
        if ch == ";":
            if _sq.complete_statement(buf):
                statements.append(buf)
                buf = ""
        i += 1
    if buf.strip():
        statements.append(buf)
    return statements

def _find_table_functions(app, sql):
    """Find table-function calls to generate as temp tables. Returns list of (start,end,name,args)."""
    out = []
    for name in ("regexp_capture", "regexp_capture_into_json", "fstat", "xpath", "generate_series"):
        for m in re.finditer(r'\b' + name + r'\s*\(', sql, re.I):
            start = m.start(); open_idx = sql.find("(", start)
            depth = 0; in_str = None; i = open_idx
            while i < len(sql):
                c = sql[i]
                if in_str:
                    if c == in_str:
                        if sql[i + 1:i + 2] == in_str:
                            i += 1
                        else:
                            in_str = None
                    while False: pass
                else:
                    if c in "'\"":
                        in_str = c
                    elif c == "(":
                        depth += 1
                    elif c == ")":
                        depth -= 1
                        if depth == 0:
                            break
                i += 1
            if i >= len(sql):
                continue
            args_text = sql[open_idx + 1:i]
            args = _split_top_level_args(args_text)
            out.append((start, i + 1, name.lower(), args))
    out.sort()
    return out

def _split_top_level_args(text):
    args = []
    depth = 0; in_str = None; cur = ""
    i = 0
    while i < len(text):
        c = text[i]
        if in_str:
            cur += c
            if c == in_str:
                if text[i + 1:i + 2] == in_str:
                    cur += text[i + 1]; i += 1
                else:
                    in_str = None
        else:
            if c in "'\"":
                in_str = c; cur += c
            elif c == "(":
                depth += 1; cur += c
            elif c == ")":
                depth -= 1; cur += c
            elif c == "," and depth == 0:
                args.append(cur.strip()); cur = ""
            else:
                cur += c
        i += 1
    if cur.strip():
        args.append(cur.strip())
    return args

def _eval_sql_scalar(app, expr):
    conn = app.ensure_db()
    params = _sql_params(app, expr)
    cur = conn.execute("SELECT (%s)" % expr, params)
    row = cur.fetchone()
    return row[0] if row else None

def _sql_params(app, sql):
    params = {}
    for v in list(app.environ.keys()):
        params[v] = app.environ.get(v)
    for i, a in enumerate(app.script_args, start=1):
        params[str(i)] = a
    return params

def _rows_for_table_function(app, name, args):
    """Returns (columns, rows) for our table-function shim."""
    if name == "generate_series":
        vals = [_eval_sql_scalar(app, a) for a in args]
        start = int(vals[0] or 0); stop = int(vals[1] or 0) if len(vals) > 1 else start
        step = int(vals[2] or 1) if len(vals) > 2 else 1
        rows = []
        if step > 0:
            v = start
            while v <= stop:
                rows.append((v,)); v += step
        elif step < 0:
            v = start
            while v >= stop:
                rows.append((v,)); v += step
        return ["value"], rows
    if name == "regexp_capture":
        s = _eval_sql_scalar(app, args[0]) if args else ""
        pat = _eval_sql_scalar(app, args[1]) if len(args) > 1 else ""
        if s is None or pat is None:
            return ["match_index", "capture_index", "capture_name", "capture_count", "range_start", "range_stop", "content"], []
        try:
            comp = re.compile(translate_regex(str(pat)))
        except Exception as e:
            raise CommandError(err_block("failed to compile SQL statement", [" reason: %s" % e]))
        rows = []
        names_by_idx = {}
        for nm, idx in comp.groupindex.items():
            names_by_idx[idx] = nm
        for midx, m in enumerate(comp.finditer(str(s))):
            count = comp.groups + 1
            rows.append((midx, 0, None, count, m.start() + 1, m.end() + 1, m.group(0)))
            for gi in range(1, comp.groups + 1):
                if m.group(gi) is None:
                    rows.append((midx, gi, names_by_idx.get(gi), count, None, None, None))
                else:
                    rows.append((midx, gi, names_by_idx.get(gi), count, m.start(gi) + 1, m.end(gi) + 1, m.group(gi)))
        return ["match_index", "capture_index", "capture_name", "capture_count", "range_start", "range_stop", "content"], rows
    if name == "regexp_capture_into_json":
        s = _eval_sql_scalar(app, args[0]) if args else ""
        pat = _eval_sql_scalar(app, args[1]) if len(args) > 1 else ""
        if s is None or pat is None:
            return ["match_index", "content"], []
        try:
            comp = re.compile(translate_regex(str(pat)))
        except Exception as e:
            raise CommandError(err_block("failed to compile SQL statement", [" reason: %s" % e]))
        rows = []
        for midx, m in enumerate(comp.finditer(str(s))):
            rows.append((midx, json.dumps(m.groupdict(), separators=(",", ":"), ensure_ascii=False)))
        return ["match_index", "content"], rows
    if name == "fstat":
        pattern = _eval_sql_scalar(app, args[0]) if args else "*"
        rows = []
        paths = sorted(glob.glob(str(pattern))) if pattern else []
        import pwd, grp
        for path in paths:
            try:
                st = os.stat(path)
                parent = os.path.dirname(path) + "/" if os.path.dirname(path) else ""
                base = os.path.basename(path)
                ftype = "reg" if stat.S_ISREG(st.st_mode) else "dir" if stat.S_ISDIR(st.st_mode) else "lnk" if stat.S_ISLNK(st.st_mode) else "chr" if stat.S_ISCHR(st.st_mode) else "blk" if stat.S_ISBLK(st.st_mode) else "fifo" if stat.S_ISFIFO(st.st_mode) else "sock" if stat.S_ISSOCK(st.st_mode) else ""
                try: user = pwd.getpwuid(st.st_uid).pw_name
                except Exception: user = str(st.st_uid)
                try: group = grp.getgrgid(st.st_gid).gr_name
                except Exception: group = str(st.st_gid)
                rows.append((parent, base, st.st_dev, st.st_ino, ftype, stat.S_IMODE(st.st_mode), st.st_nlink, st.st_uid, user, st.st_gid, group, st.st_rdev, st.st_size, 4096, st.st_blocks, fmt_log_time(datetime.datetime.fromtimestamp(st.st_atime)), fmt_log_time(datetime.datetime.fromtimestamp(st.st_mtime)), fmt_log_time(datetime.datetime.fromtimestamp(st.st_ctime)), None))
            except Exception as e:
                rows.append((os.path.dirname(str(pattern)), os.path.basename(str(pattern)), None, None, None, None, None, None, None, None, None, None, None, None, None, None, None, None, str(e)))
        return ["st_parent", "st_name", "st_dev", "st_ino", "st_type", "st_mode", "st_nlink", "st_uid", "st_user", "st_gid", "st_group", "st_rdev", "st_size", "st_blksize", "st_blocks", "st_atime", "st_mtime", "st_ctime", "error"], rows
    if name == "xpath":
        xp = _eval_sql_scalar(app, args[0]) if args else ""
        xml = _eval_sql_scalar(app, args[1]) if len(args) > 1 else ""
        rows = []
        if xml:
            try:
                import xml.etree.ElementTree as ET
                root = ET.fromstring(str(xml))
                # build a tag-only path lookup
                def find(path):
                    segs = [s for s in path.split("/") if s]
                    if not segs:
                        return []
                    if root.tag != segs[0]:
                        # treat path as relative
                        cand = [root]
                    else:
                        cand = [root]; segs = segs[1:]
                    for seg in segs:
                        nxt = []
                        for el in cand:
                            for child in el:
                                if child.tag == seg:
                                    nxt.append(child)
                        cand = nxt
                    return cand
                for el in find(str(xp)):
                    xml_str = ET.tostring(el, encoding="unicode") + "\n"
                    rows.append((xml_str, str(xp), json.dumps(dict(el.attrib), separators=(",", ":")), el.text or ""))
            except Exception:
                pass
        return ["result", "node_path", "node_attr", "node_text"], rows
    return [], []

def _execute_sql(app, sql, source_label="command-option:1"):
    """Executes one ';' command worth of SQL. Raises CommandError on failure."""
    text = sql.strip()
    if not text:
        return
    # dot commands
    if text.startswith("."):
        _execute_sql_dot(app, text, source_label)
        return
    if re.match(r'(?i)^from\s', text):
        raise CommandError("  error: PRQL is not supported in this build\n")
    app.refresh_db()
    conn = app.ensure_db()
    statements = _split_sql_statements(sql)
    had_result = False
    for stmt in statements:
        s = stmt.strip()
        if not s:
            continue
        if s.endswith(";"):
            s_core = s[:-1].rstrip()
        else:
            s_core = s
        # PRAGMA table_info/table_xinfo interception
        pm = re.match(r'(?is)^PRAGMA\s+(table_info|table_xinfo)\s*\(\s*\'?\"?([^\'\")]+)\'?\s*\)\s*$', s_core.strip())
        if pm:
            kind = pm.group(1).lower(); tname = pm.group(2).strip().strip('"')
            cols = _pragma_columns(app, tname)
            if kind == "table_info":
                out_cols = ["cid", "name", "type", "notnull", "dflt_value", "pk"]
                rows = [(c[0], c[1], c[2], c[3], c[4], c[5]) for c in cols]
            else:
                out_cols = ["cid", "name", "type", "notnull", "dflt_value", "pk", "hidden"]
                rows = [tuple(c) for c in cols]
            app.db_result = (out_cols, rows)
            had_result = True
            continue
        # table functions
        funcs = _find_table_functions(app, s_core)
        stmt_to_run = s
        tmp_tables = []
        if funcs:
            # replace from the end to keep offsets valid
            for idx, (start, end, name, args) in enumerate(reversed(funcs)):
                cols, rows = _rows_for_table_function(app, name, args)
                tmp_name = "__lnav_tf_%d" % idx
                try:
                    conn.execute("DROP TABLE IF EXISTS %s" % quote_id(tmp_name))
                except Exception:
                    pass
                conn.execute("CREATE TABLE %s (%s)" % (quote_id(tmp_name), ", ".join(quote_id(c) for c in cols)))
                if rows:
                    conn.executemany("INSERT INTO %s VALUES (%s)" % (quote_id(tmp_name), ", ".join("?" for _ in cols)), rows)
                tmp_tables.append(tmp_name)
                stmt_to_run = stmt_to_run[:start] + tmp_name + stmt_to_run[end:]
        try:
            params = _sql_params(app, stmt_to_run)
            # environment vars set by prior statements must be visible
            params.update({k: v for k, v in app.environ.items()})
            cur = conn.execute(stmt_to_run, params)
        except _SqlRaise as e:
            raise CommandError("  error: %s\n" % str(e) + snippet_block(source_label, ";" + sql))
        except Exception as e:
            msg = str(e)
            raise CommandError(_sql_error_block(msg, stmt_to_run, sql, source_label))
        if cur.description is not None:
            cols = [d[0] for d in cur.description]
            rows = cur.fetchall()
            rows = [tuple(r) for r in rows]
            cols, rows = _apply_star_filter(sql, cols, rows)
            app.db_result = (cols, rows)
            had_result = True
            # environment assignment from the first row
            if rows:
                for cname, val in zip(cols, rows[0]):
                    app.environ[cname] = val
            # switch to db view
            if app.current_view_name != "db":
                app.view_stack.append("db")
                # de-dup keeping last
                seen = []
                for n in app.view_stack:
                    if n in seen:
                        seen.remove(n)
                    seen.append(n)
                app.view_stack = seen
        try:
            conn.commit()
        except Exception:
            pass
    app.sync_from_db()
    return had_result

def _sql_error_block(msg, stmt_to_run, orig_sql, source_label):
    # original: compile errors reference the statement without the leading ';'
    snippet = orig_sql.strip()
    out = "  error: failed to compile SQL statement\n"
    out += " reason: %s\n" % msg
    out += snippet_block(source_label, snippet)
    return out

def _execute_sql_dot(app, text, source_label):
    m = re.match(r'^\.(\w+)\s*(.*)$', text, re.S)
    if not m:
        raise CommandError(_sql_error_block('near ".": syntax error', text, text, source_label))
    cmd = m.group(1); rest = m.group(2).strip()
    if cmd == "schema":
        _write_stdout(app, schema_text(app) + ("" if schema_text(app).endswith("\n") else "\n"))
        app.echo_stdout_used = True
        app.suppress_final = True
        # schema also switches to schema view in the reference; headless dump of
        # the schema view would duplicate output, so mark it as printed.
        return
    if cmd == "dump":
        args = _split_top_level_args(rest.replace(" ", ",")) if rest else []
        args = [a for chunk in rest.split() for a in [chunk] if a]
        if not args:
            raise CommandError("  error: expecting a file name to write to\n" + snippet_block(source_label, ";" + text) + _dot_help(".dump"))
        if len(args) < 2:
            raise CommandError("  error: expecting a table name to dump\n" + snippet_block(source_label, ";" + text) + _dot_help(".dump"))
        path, tables = args[0], args[1:]
        try:
            _dump_tables(app, path, tables)
        except CommandError:
            raise
        return
    if cmd == "read":
        if not rest:
            raise CommandError("  error: expecting a file name to read\n" + snippet_block(source_label, ";" + text) + _dot_help(".read"))
        path = rest.split()[0]
        if not os.path.exists(path):
            raise CommandError("  error: unable to read script file: %s -- No such file or directory\n" % path + snippet_block(source_label, ";" + text) + _dot_help(".read"))
        with open(path) as fh:
            content = fh.read()
        for stmt in _split_sql_statements(content):
            _execute_sql(app, stmt, source_label)
        return
    if cmd == "save":
        if not rest:
            raise CommandError("  error: expecting a file name to write to\n" + snippet_block(source_label, ";" + text) + _dot_help(".save"))
        path = rest.split()[0]
        app.refresh_db()
        conn = app.ensure_db()
        try:
            import sqlite3
            dest = sqlite3.connect(path)
            conn.backup(dest)
            dest.close()
        except Exception as e:
            raise CommandError("  error: unable to save database: %s\n" % e)
        return
    # other dot commands are syntax errors at the SQL level
    raise CommandError(_sql_error_block('near ".": syntax error', text, text, source_label))

def _dot_help(cmd):
    helps = {
        ".dump": " = help: ;.dump path table1 [... tableN]\n         " + "═" * 70 + "\n           Dump one or more tables to a file as a series of SQL statements\n",
        ".read": " = help: ;.read path\n         " + "═" * 70 + "\n           Execute the SQLite statements in the given file\n",
        ".save": " = help: ;.save path\n         " + "═" * 70 + "\n           Save the current database to a SQLite file\n",
    }
    return helps.get(cmd, "")

def _dump_tables(app, path, tables):
    app.refresh_db()
    conn = app.ensure_db()
    try:
        fh = open(path, "w")
    except Exception as e:
        raise CommandError("  error: unable to open file -- %s\n" % path)
    with fh:
        fh.write("PRAGMA foreign_keys=OFF;\nBEGIN TRANSACTION;\n")
        for tname in tables:
            try:
                cur = conn.execute("SELECT * FROM %s" % quote_id(tname))
            except Exception as e:
                raise CommandError(_sql_error_block(str(e), tname, tname, "command-option:1"))
            cols = [d[0] for d in cur.description]
            _v, allc = (None, None)
            # use only visible columns for log tables
            rows = cur.fetchall()
            for row in rows:
                vals = []
                rowd = dict(zip(cols, row))
                # filter hidden columns out of the dump (match observed dumps)
                use_cols = [c for c in cols if c not in SQL_HIDDEN_COLUMNS]
                for c in use_cols:
                    vals.append(_sql_literal(rowd.get(c)))
                fh.write("INSERT INTO %s VALUES(%s);\n" % (tname, ",".join(vals)))
        fh.write("COMMIT;\n")

def _sql_literal(v):
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "1" if v else "0"
    if isinstance(v, (int, float)):
        return format_float(v) if isinstance(v, float) else str(v)
    if isinstance(v, (bytes, bytearray)):
        return "X'" + bytes(v).hex() + "'"
    return "'" + str(v).replace("'", "''") + "'"

def _apply_star_filter(orig_sql, cols, rows):
    # determine which hidden columns were explicitly selected
    keep = set()
    sql_no_strings = re.sub(r"'[^']*'", "''", orig_sql)
    # find select lists
    for m in re.finditer(r'(?i)\bSELECT\b', sql_no_strings):
        start = m.end()
        # scan to FROM at same depth or end
        depth = 0; i = start; end = len(sql_no_strings)
        while i < len(sql_no_strings):
            c = sql_no_strings[i]
            if c == "(":
                depth += 1
            elif c == ")":
                if depth == 0:
                    end = i; break
                depth -= 1
            elif depth == 0 and sql_no_strings[i:i + 4].upper() == "FROM" and (i == 0 or not (sql_no_strings[i - 1].isalnum() or sql_no_strings[i - 1] == "_")):
                end = i; break
            i += 1
        sel = sql_no_strings[start:end]
        for item in _split_top_level_args(sel):
            it = item.strip()
            if it == "*" or it.endswith(".*"):
                continue
            for hm in re.finditer(r'"?([A-Za-z_][\w]*)"?', it):
                if hm.group(1) in SQL_HIDDEN_COLUMNS:
                    keep.add(hm.group(1))
    if not cols:
        return cols, rows
    idxs = []
    newcols = []
    for i, c in enumerate(cols):
        if c in SQL_HIDDEN_COLUMNS and c not in keep:
            continue
        idxs.append(i); newcols.append(c)
    if len(idxs) == len(cols):
        return cols, rows
    newrows = [tuple(r[i] for i in idxs) for r in rows]
    return newcols, newrows

def _pragma_columns(app, tname):
    """Synthesize PRAGMA table_info/xinfo rows: (cid,name,type,notnull,dflt,pk,hidden)."""
    cols = _table_all_columns(app, tname)
    out = []
    for i, (name, typ, hidden, pk) in enumerate(cols):
        out.append((i, name, typ, 0, None, pk, hidden))
    return out

