        sys.stdout.flush()

def _write_stderr(text):
    sys.stderr.write(text)
    sys.stderr.flush()

class CommandError(Exception):
    """An error that should be reported to stderr in lnav style (exit stays 0 in headless)."""
    def __init__(self, text):
        super().__init__(text)
        self.text = text

def err_block(first_line, extra_lines=None):
    out = "  error: %s\n" % first_line
    for ln in (extra_lines or []):
        out += ln + "\n"
    return out

def snippet_block(source_label, content, caret=None, caret_msg=None):
    content_line = content
    out = " --> %s\n" % source_label
    out += " | %s\n" % (content_line.ljust(40) if len(content_line) < 40 else content_line)
    if caret is not None:
        out += " | %s%s" % (" " * caret, "^")
        if caret_msg:
            out += " " + caret_msg
        out += "\n"
    return out

def help_block_for_command(cmds_help, name):
    info = cmds_help.get(name)
    if info is None:
        return ""
    sig, desc_lines = info
    out = " = help: %s\n" % sig
    out += "         " + "═" * 70 + "\n"
    for ln in desc_lines:
        out += "           %s\n" % ln
    return out

