def _execute_sql_dot(app, text, source_label):
    m = re.match(r'^\.(\w+)\s*(.*)$', text, re.S)
    if not m:
        raise CommandError(_sql_error_block('near ".": syntax error', text, text, source_label))
    cmd = m.group(1); rest = m.group(2).strip()
    if cmd == "schema":
