        # the schema view would duplicate output, so mark it as printed.
        return
    if cmd == "dump":
        args = _split_top_level_args(rest.replace(" ", ",")) if rest else []
        args = [a for chunk in rest.split() for a in [chunk] if a]
        if not args:
            raise CommandError("  error: expecting a file name to write to\n" + snippet_block(source_label, ";" + text) + _dot_help(".dump"))
        if len(args) < 2:
            raise CommandError("  error: expecting a table name to dump\n" + snippet_block(source_label, ";" + text) + _dot_help(".dump"))
        path, tables = args[0], args[1:]
        try:
            _dump_tables(app, path, tables)
        except CommandError:
            raise
        return
    if cmd == "read":
        if not rest:
            raise CommandError("  error: expecting a file name to read\n" + snippet_block(source_label, ";" + text) + _dot_help(".read"))
        path = rest.split()[0]
        if not os.path.exists(path):
            raise CommandError("  error: unable to read script file: %s -- No such file or directory\n" % path + snippet_block(source_label, ";" + text) + _dot_help(".read"))
        with open(path) as fh:
            content = fh.read()
        for stmt in _split_sql_statements(content):
            _execute_sql(app, stmt, source_label)
        return
    if cmd == "save":
        if not rest:
            raise CommandError("  error: expecting a file name to write to\n" + snippet_block(source_label, ";" + text) + _dot_help(".save"))
        path = rest.split()[0]
        app.refresh_db()
        conn = app.ensure_db()
        try:
            import sqlite3
            dest = sqlite3.connect(path)
            conn.backup(dest)
            dest.close()
        except Exception as e:
            raise CommandError("  error: unable to save database: %s\n" % e)
        return
