def _dot_help(cmd):
    helps = {
        ".dump": " = help: ;.dump path table1 [... tableN]\n         " + "═" * 70 + "\n           Dump one or more tables to a file as a series of SQL statements\n",
        ".read": " = help: ;.read path\n         " + "═" * 70 + "\n           Execute the SQLite statements in the given file\n",
        ".save": " = help: ;.save path\n         " + "═" * 70 + "\n           Save the current database to a SQLite file\n",
