    # determine which hidden columns were explicitly selected
    keep = set()
    sql_no_strings = re.sub(r"'[^']*'", "''", orig_sql)
    # find select lists
    for m in re.finditer(r'(?i)\bSELECT\b', sql_no_strings):
        start = m.end()
        # scan to FROM at same depth or end
        depth = 0; i = start; end = len(sql_no_strings)
        while i < len(sql_no_strings):
            c = sql_no_strings[i]
            if c == "(":
                depth += 1
            elif c == ")":
                if depth == 0:
                    end = i; break
                depth -= 1
            elif depth == 0 and sql_no_strings[i:i + 4].upper() == "FROM" and (i == 0 or not (sql_no_strings[i - 1].isalnum() or sql_no_strings[i - 1] == "_")):
                end = i; break
            i += 1
        sel = sql_no_strings[start:end]
        for item in _split_top_level_args(sel):
            it = item.strip()
            if it == "*" or it.endswith(".*"):
                continue
            for hm in re.finditer(r'"?([A-Za-z_][\w]*)"?', it):
                if hm.group(1) in SQL_HIDDEN_COLUMNS:
                    keep.add(hm.group(1))
