        line = lines[i]
        if re.match(r'^[:;][\S]+', line) and i + 1 < len(lines) and lines[i + 1].startswith("═"):
            sig = line.strip()
            name = sig.split()[0]
            desc = []
            j = i + 2
            while j < len(lines):
                ln = lines[j]
                if ln.startswith("  ") and ln.strip() and not ln.startswith("   "):
                    desc.append(ln[2:].rstrip()); j += 1; continue
                if ln.startswith("  ") and ln.strip():
                    desc.append(ln[2:].rstrip()); j += 1; continue
                break
            # strip a possibly included parameter section start
            desc_clean = []
            for d in desc:
                if d in ("Parameter", "Parameters", "See Also", "Example", "Examples"):
                    break
                desc_clean.append(d)
            key = name[1:] if name.startswith(":") else name
            cmds[key] = (sig, desc_clean)
            i = j
        else:
            i += 1
    return cmds

