def _cmd_error(app, msg, cmd_text=None, source_label="command-option:1", cmd_name=None, reason=None, show_help=True):
    out = "  error: %s\n" % msg
    if reason:
        out += " reason: %s\n" % reason
    if cmd_text:
        out += snippet_block(source_label, cmd_text)
    if show_help and cmd_name:
        out += help_block_for_command(COMMANDS_HELP, cmd_name)
    return CommandError(out)

def _parse_time_arg(app, text):
    """Parse a timestamp argument used by :goto / since / until."""
    if text is None:
        return None
    s = text.strip()
    if not s:
        return None
    pt = parse_timestamp(s)
    if pt is not None and pt.has_date:
        return pt.dt
    # relative offsets like +1h, -30m, 1 day, etc.
    m = re.match(r'^([+-]?\d+(?:\.\d+)?)\s*(s|sec|secs|m|min|mins|h|hr|hrs|d|day|days|w|week|weeks)$', s, re.I)
    if m:
        n = float(m.group(1)); unit = m.group(2).lower()
        secs = {"s":1,"sec":1,"secs":1,"m":60,"min":60,"mins":60,"h":3600,"hr":3600,"hrs":3600,"d":86400,"day":86400,"days":86400,"w":604800,"week":604800,"weeks":604800}[unit] * n
        base = app._focused_message().timestamp if app._focused_message() else _now_local().replace(tzinfo=None)
        return base + datetime.timedelta(seconds=secs)
    if pt is not None and not pt.has_date:
        # time of day: use the date of the first/ focused message
        msg = app._focused_message()
        base_date = msg.timestamp.date() if msg and msg.timestamp else _now_local().date()
        return datetime.datetime.combine(base_date, pt.dt.time())
    return None

def parse_since_until(text, kind):
    """Validators for --since/--until; raises ValueError with (reason, note, help) info."""
    s = (text or "").strip()
    if not s:
        raise ValueError("Unrecognized input")
    # relative durations like "1h", "2 days ago"
    m = re.match(r'^(\d+(?:\.\d+)?)\s*(s|sec|secs|second|seconds|m|min|mins|minute|minutes|h|hr|hrs|hour|hours|d|day|days|w|week|weeks)( ago)?$', s, re.I)
    if m:
        n = float(m.group(1)); unit = m.group(2).lower()
        secs = {"s":1,"sec":1,"secs":1,"second":1,"seconds":1,"m":60,"min":60,"mins":60,"minute":60,"minutes":60,"h":3600,"hr":3600,"hrs":3600,"hour":3600,"hours":3600,"d":86400,"day":86400,"days":86400,"w":604800,"week":604800,"weeks":604800}[unit] * n
        return _now_local().replace(tzinfo=None) - datetime.timedelta(seconds=secs)
    # numbers without a unit are rejected with a specific reason (observed)
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        pt = parse_timestamp(s)
        return pt.dt if pt else None
    pt = parse_timestamp(s)
    if pt is not None and pt.has_date:
        return pt.dt
    # figure out a reason like the reference
    if re.match(r'^\d', s):
        # look for a matched date prefix
        m2 = re.match(r'^(\d{4}-\d{2}-\d{2})(.*)$', s)
        if m2 and m2.group(2):
            raise _TimeArgError("the leading part of the timestamp was matched, however, the trailing text “%s” was not" % m2.group(2), note='input matched time format “%Y-%m-%d”')
        if re.match(r'^\d+$', s):
            raise _TimeArgError("No time unit given for the previous number")
        raise _TimeArgError("Unrecognized input")
    raise _TimeArgError("Unrecognized input")

class _TimeArgError(ValueError):
    def __init__(self, reason, note=None):
        super().__init__(reason)
        self.reason = reason
        self.note = note

