def execute_command(app, cmd_text, source_label="command-option:1"):
    """Executes a single command string (starting with :, ;, |, or /)."""
    if cmd_text is None:
        return
    raw = cmd_text
    stripped = cmd_text.lstrip()
    if not stripped:
        return
    kind = stripped[0]
    if kind == ";":
        sql = stripped[1:]
        try:
            _execute_sql(app, sql, source_label)
        except CommandError:
            raise
        except Exception as e:
            raise CommandError(_sql_error_block(str(e), sql, sql, source_label))
        return
    if kind == "|":
        _execute_script_ref(app, stripped[1:].strip(), raw, source_label)
        return
    if kind == "/":
        pattern = stripped[1:]
        app.views[app.current_view_name]["search"] = pattern
        return
    if kind != ":":
        # treat as a plain search? (observed behaviour for stray text is an error at the CLI)
        raise _cmd_error(app, "unknown command: “%s”" % stripped.split()[0], show_help=False)
    body = stripped[1:]
    if not body.strip():
        return
    m = re.match(r'^(\S+)(?:\s+(.*))?$', body, re.S)
    name = m.group(1)
    rest = m.group(2) if m.group(2) is not None else ""
    _dispatch_command(app, name, rest, raw, source_label)

def _execute_script_ref(app, ref, raw=None, source_label="command-option:1"):
    # ref: path or script name, followed by arguments
    if not ref:
        raise _cmd_error(app, "expecting a script to execute", raw, source_label, None)
    parts = _split_script_args(ref)
    if not parts:
        raise _cmd_error(app, "expecting a script to execute", raw, source_label, None)
    target, args = parts[0], parts[1:]
    path = _find_script(app, target)
    if path is None:
        raise CommandError("  error: unknown script -- %s -- file not found\n" % target + snippet_block(source_label, raw or ("|" + ref)))
    old_args = app.script_args
    app.script_args = [str(a) for a in args]
    try:
        with open(path, "r", encoding="utf-8", errors="surrogateescape") as fh:
            content = fh.read()
        _execute_script_content(app, content, path)
    finally:
        app.script_args = old_args

def _split_script_args(ref):
    try:
        return shlex.split(ref)
    except Exception:
        return ref.split()

def _find_script(app, target):
    if os.path.isfile(target):
        return target
    # search the config dirs for a script with this name (+ .lnav)
    search_roots = []
    if app.dotlnav:
        search_roots.append(app.dotlnav)
    for d in app.include_dirs:
        search_roots.append(d)
    search_roots.extend(["/etc/lnav", "/usr/etc/lnav"])
    for root in search_roots:
        if not root or not os.path.isdir(root):
            continue
        for dirpath, _dirs, files in os.walk(root):
            for fn in files:
                if fn == target or fn == target + ".lnav" or os.path.splitext(fn)[0] == target:
                    return os.path.join(dirpath, fn)
    return None

def _execute_script_content(app, content, path=None):
    lines = content.splitlines()
    for ln in lines:
        stripped = ln.strip()
        if not stripped or stripped.startswith("#"):
            continue
        expanded = _expand_vars(app, ln)
        # a script line can be a full command (kept as-is if prefixed, else default to a command)
        execute_command(app, expanded, source_label="command-option:1")

def _expand_vars(app, text):
    def repl(m):
        name = m.group(1) or m.group(2)
        if name is None:
            return "$"
        if name.isdigit():
            idx = int(name)
            if 1 <= idx <= len(app.script_args):
                return str(app.script_args[idx - 1])
            return ""
        if name in app.environ:
            v = app.environ.get(name)
            return "<NULL>" if v is None else str(v)
        return ""
    # script argument $1.. and $name / ${name}; $$ is a literal $
    text = text.replace("$$", "\x00DOLLAR\x00")
    text = re.sub(r'\$\{([A-Za-z_][\w]*)\}|\$([A-Za-z_][\w]*|\d+)', repl, text)
    return text.replace("\x00DOLLAR\x00", "$")

