    if name == "quit":
        return
    if name == "alt-msg":
        return
    if name == "cd":
        target = rest.strip()
        if target:
            try:
                os.chdir(os.path.expanduser(target))
            except Exception as e:
                raise _cmd_error(app, "cannot change directory: %s" % target, raw, source_label, name, reason=str(e))
        return
    if name == "echo":
        no_newline = False
        text = rest
        if text == "-n" or text.startswith("-n "):
            no_newline = True
            text = text[3:] if text.startswith("-n ") else ""
        out = _expand_vars(app, text)
        if app.redirect_file is not None:
            _write_stdout(app, out + ("" if no_newline else "\n"))
