def _cmd_goto(app, arg, raw, source_label):
    view = app.current_view_name
    v = app.views[view]
    if not arg:
        raise _cmd_error(app, "expecting a line number, timestamp, or percentage", raw, source_label, "goto")
    lines = view_lines(app, view)
    if view == "log":
        msgs = filtered_messages(app)
        if not msgs:
            return
        target = None
        if arg.startswith("#"):
            for m in msgs:
                link = "#msg%08x-v1:%s" % (m.global_index * 7919 % 0x7fffffff, md5_hex(m.log_text.encode("utf-8", "surrogateescape")))
                if arg == link or arg.lstrip("#") in link:
                    target = m.global_index; break
            if target is None:
                raise CommandError("  error: unable to find anchor: %s\n" % arg + snippet_block(source_label, raw) + help_block_for_command(COMMANDS_HELP, "goto"))
        elif arg.endswith("%"):
            try:
                pct = float(arg[:-1])
            except Exception:
                raise _cmd_error(app, "invalid argument: %s" % arg, raw, source_label, "goto", reason="expecting line number/percentage, timestamp, or relative time")
            target = int(len(msgs) * pct / 100.0)
            target = msgs[min(max(target, 0), len(msgs) - 1)].global_index
        elif re.match(r'^-?\d+$', arg):
            n = int(arg)
            target = msgs[min(max(n, 0), len(msgs) - 1)].global_index if n < len(msgs) else msgs[-1].global_index
            if n < 0:
                target = msgs[0].global_index
        else:
            dt = _parse_time_arg(app, arg)
            if dt is None:
                raise _cmd_error(app, "invalid argument: %s" % arg, raw, source_label, "goto", reason="expecting line number/percentage, timestamp, or relative time")
            target = msgs[-1].global_index
            for m in msgs:
                if m.timestamp and m.timestamp >= dt:
                    target = m.global_index; break
        v["top"] = target; v["selection"] = target
        return
    # other views: line numbers are row indexes
    if arg.endswith("%"):
        try:
            pct = float(arg[:-1])
        except Exception:
            raise _cmd_error(app, "invalid argument: %s" % arg, raw, source_label, "goto", reason="expecting line number/percentage, timestamp, or relative time")
        idx = int(len(lines) * pct / 100.0)
    elif re.match(r'^-?\d+$', arg):
        idx = int(arg)
    else:
        dt = _parse_time_arg(app, arg)
        if dt is None:
            raise _cmd_error(app, "invalid argument: %s" % arg, raw, source_label, "goto", reason="expecting line number/percentage, timestamp, or relative time")
        idx = 0
    idx = min(max(idx, 0), max(0, len(lines) - 1)) if lines else 0
    v["top"] = idx; v["selection"] = idx

def _cmd_relative_goto(app, arg, raw, source_label):
    view = app.current_view_name
    v = app.views[view]
    if not arg:
        raise _cmd_error(app, "expecting a line count", raw, source_label, "relative-goto")
    try:
        if arg.endswith("%"):
            pct = float(arg[:-1])
            msgs = filtered_messages(app) if view == "log" else view_lines(app, view)
            delta = int(len(msgs) * pct / 100.0)
        else:
            delta = int(arg)
    except Exception:
        raise _cmd_error(app, "invalid argument: %s" % arg, raw, source_label, "relative-goto")
    if view == "log":
        msgs = filtered_messages(app)
        if not msgs:
            return
        cur = v.get("selection", 0) or 0
        # position of cur in filtered list
        pos = next((i for i, m in enumerate(msgs) if m.global_index >= (cur or 0)), 0)
        np_ = min(max(pos + delta, 0), len(msgs) - 1)
        v["top"] = msgs[np_].global_index; v["selection"] = msgs[np_].global_index
    else:
        lines = view_lines(app, view)
        idx = min(max((v.get("top", 0) or 0) + delta, 0), max(0, len(lines) - 1))
        v["top"] = idx; v["selection"] = idx

