    if not cmdline:
        raise _cmd_error(app, "expecting a shell command", raw, source_label, "sh")
    idx = getattr(app, "_sh_counter", 0)
    app._sh_counter = idx + 1
    display_name = "sh-%d %s" % (idx, cmdline)
    try:
        p = subprocess.run(cmdline, shell=True, capture_output=True, timeout=60)
        raw_bytes = (p.stdout or b"") + (p.stderr or b"")
    except Exception:
        raw_bytes = b""
    _store_piper(app, display_name, raw_bytes)
    lf = app.add_file_content(display_name, raw_bytes, kind="sh")
    app.rebuild_messages()
