            since = args[i + 1]; i += 2; continue
        if args[i] == "--until" and i + 1 < len(args):
            until = args[i + 1]; i += 2; continue
        paths.append(args[i]); i += 1
    for path in paths:
        ok, err = load_path_into_app(app, path)
        if not ok:
            raise CommandError("  error: cannot open file: %s\n reason: %s\n" % (path, err) + snippet_block(source_label, raw) + " = help: make sure the file exists and is accessible\n")

def _cmd_close(app, rest, raw, source_label):
