def _read_piper_bytes(path):
    """Parse a piper capture file, returning (header, records, plain_bytes)."""
    try:
        data = open(path, "rb").read()
    except Exception:
        return None, [], b""
    if len(data) < 8 or data[:1] != b"L" or data[2:3] != b"N":
        return None, [], data
    hlen = int.from_bytes(data[6:8], "big")
    try:
