def app_recursive(app):
    return bool(getattr(app, "recursive", False))

def _rotated_siblings(canon):
    directory = os.path.dirname(canon) or "."
    base = os.path.basename(canon)
    # strip a trailing rotation number to find the base
    m = re.match(r'^(.*?)(?:\.(\d+)(?:\.(?:gz|bz2|xz|zst))?)$', base)
    root_base = base
    if m and os.path.exists(os.path.join(directory, m.group(1))):
        root_base = m.group(1)
    out = []
    plain = os.path.join(directory, root_base)
    if os.path.isfile(plain):
        out.append(plain)
    rots = []
    for fn in os.listdir(directory):
        mm = re.match(r'^' + re.escape(root_base) + r'\.(\d+)(?:\.(?:gz|bz2|xz|zst))?$', fn)
        if mm:
            rots.append((int(mm.group(1)), os.path.join(directory, fn)))
    for _n, p in sorted(rots):
        out.append(p)
    return out or [canon]

def _fetch_url(url):
    from urllib.request import urlopen, Request
    from urllib.error import URLError
    try:
        req = Request(url, headers={"User-Agent": "curl/7.81.0"})
        with urlopen(req, timeout=10) as resp:
            return resp.read()
    except URLError as e:
        from urllib.parse import urlparse
        u = urlparse(url)
        host = u.hostname or ""
        port = u.port or (443 if u.scheme == "https" else 80)
        reason = str(getattr(e, "reason", e))
        if "Name or service not known" in reason or "Temporary failure" in reason or "getaddrinfo" in reason:
            return ("Could not resolve host: %s\n" % host).encode()
        if "Connection refused" in reason:
            return ("Failed to connect to %s port %d after 0 ms: Connection refused\n" % (host, port)).encode()
        return ("%s\n" % reason).encode()
    except Exception as e:
        return ("%s\n" % e).encode()

