def parse_main_args(argv):
    """Returns (opts, positionals). Raises CliExit with the proper code/output."""
    opts = {"flags": set(), "commands": [], "debug": [], "shell": [], "scripts": [], "include": [], "since": [], "until": [], "items": []}
    positionals = []
    unknowns = []
    missing = []
    i = 0
    after_dd = False
    args = argv
    while i < len(args):
        tok = args[i]
        if after_dd:
            positionals.append(tok); i += 1; continue
        if tok == "--":
            after_dd = True; i += 1; continue
        if tok.startswith("--"):
            if "=" in tok:
                name, val = tok.split("=", 1)
                has_val = True
            else:
                name, val, has_val = tok, None, False
            if name in MAIN_LONG:
                ch = MAIN_LONG[name]
                if ch in ("h", "V"):
                    opts["flags"].add(ch)
                else:
                    if not has_val:
                        if i + 1 < len(args):
                            val = args[i + 1]; i += 1
                        else:
                            missing.append(MAIN_VALUE_OPTS[ch][0]); i += 1; continue
                    opts[MAIN_VALUE_OPTS[ch][1]].append(val)
                    if ch == "S":
                        opts["items"].append(("since", val))
                i += 1; continue
            unknowns.append(tok); i += 1; continue
        if tok.startswith("-") and tok != "-" and len(tok) > 1 and not tok[1].isdigit():
            # bundled short options
            j = 1
            consumed_value = False
            while j < len(tok):
                ch = tok[j]
                if ch == "i":
                    opts["flags"].add("i"); j += 1; continue
                if ch in MAIN_FLAGS:
                    opts["flags"].add(ch); j += 1; continue
                if ch in MAIN_VALUE_OPTS:
                    rest = tok[j + 1:]
                    if rest.startswith(":"):
                        rest = rest[1:]
                    if rest != "":
                        val = rest
                    elif i + 1 < len(args):
                        val = args[i + 1]; i += 1
                    else:
                        missing.append(MAIN_VALUE_OPTS[ch][0])
                        val = None
                    if val is not None:
                        key = MAIN_VALUE_OPTS[ch][1]
                        opts[key].append(val)
                        if key == "commands":
                            opts["items"].append(("cmd", val))
                        elif key == "scripts":
                            opts["items"].append(("file", val))
                    consumed_value = True
                    break
                # unknown
                unknowns.append(tok if j == 1 else "-" + tok[j:])
                break
            i += 1; continue
        positionals.append(tok); i += 1
    return opts, positionals, unknowns, missing

def _main_cli_error(reason, code=109):
    sys.stderr.write("  error: invalid command-line arguments\n reason: %s\n" % reason)
    raise CliExit(code)

def run_main(argv):
    argv0 = argv[0] if argv else "./executable"
