            _write_stderr("  error: invalid command-line arguments\n reason: -c: empty commands are not allowed\n")
            return 105
        if cmd[0] not in ":;|/":
            out = "  error: invalid value for “-c” option\n"
            out += " --> command-line argument\n"
            out += " |  %s\n" % ("-c " + cmd).ljust(40)
            out += " |     ^ command type prefix is missing    \n"
            out += " = help: command arguments must start with one of the following symbols to denote the type of command:\n"
            out += "            : - an lnav command   (e.g. :goto 42)\n"
            out += "            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)\n"
            out += "            | - an lnav script    (e.g. |rename-stdin foo)\n"
            _write_stderr(out)
            return 105
    if missing:
        _write_stderr("  error: invalid command-line arguments\n reason: %s\n" % missing[0])
        return 114
    # -I validation (after missing, before help)
    for inc in opts["include"]:
        if not os.path.isdir(inc):
            _write_stderr("  error: invalid command-line arguments\n reason: -I: Directory does not exist: %s\n" % inc)
            return 105
    app.include_dirs = list(opts["include"])
    # version / help
    if "V" in flags:
        sys.stdout.write(VERSION + "\n")
        return 0
    if "h" in flags:
        # help needs paths, but does not create ~/.lnav
        _print_main_help(app, argv0 if "/" in argv0 or True else app.bin_path)
        return 0
    if unknowns:
        rev = list(reversed(unknowns))
        if len(rev) == 1:
            _write_stderr("  error: invalid command-line arguments\n reason: The following argument was not expected: %s\n" % rev[0])
        else:
            _write_stderr("  error: invalid command-line arguments\n reason: The following arguments were not expected: %s\n" % " ".join(rev))
        return 109
    if "i" in flags and not positionals:
        _write_stderr("  error: invalid command-line arguments\n reason: -i requires file\n")
        return 107
    # since/until semantic validation
    since_dt = None; until_dt = None
    for val in opts["since"]:
        try:
            since_dt = parse_since_until(val, "since")
        except _TimeArgError as e:
            out = "  error: invalid 'since' time “%s”\n reason: %s\n" % (val, e.reason)
            if getattr(e, "note", None):
                out += " = note: %s\n" % e.note
                out += " = help: fix the timestamp or remove the trailing text\n"
            _write_stderr(out)
            return 1
    for val in opts["until"]:
        try:
            until_dt = parse_since_until(val, "until")
        except _TimeArgError as e:
            out = "  error: invalid 'until' time “%s”\n reason: %s\n" % (val, e.reason)
            if getattr(e, "note", None):
                out += " = note: %s\n" % e.note
                out += " = help: fix the timestamp or remove the trailing text\n"
            _write_stderr(out)
            return 1
    app.since = since_dt; app.until = until_dt
    app.quiet = "q" in flags
    app.recursive = "r" in flags
    app.load_rotated = "R" in flags
    if opts["debug"]:
        app.debug_path = opts["debug"][-1]
        write_debug_log(app)
    # startup: directories, formats, config
    app.registry = get_registry(app.include_dirs, app.dotlnav)
    app.init_dirs()
    app.load_config()
    fmt_err = validate_custom_formats(app)
    if fmt_err:
        _write_stderr(fmt_err)
        return 1
    if "i" in flags:
        return run_install(app, positionals)
    if "u" in flags and not positionals and not opts["items"] and not opts["shell"]:
        sys.stdout.write("No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n")
        return 0
    if "C" in flags:
        return run_check(app, positionals)
    headless = "n" in flags
    # ---------- source loading ----------
    load_errors = []
    files_to_load = list(positionals)
    stdin_bytes = None
    stdin_is_tty = True
    try:
        stdin_is_tty = sys.stdin.isatty()
    except Exception:
        stdin_is_tty = False
    want_stdin_script = ("-" in opts["scripts"])
    if not stdin_is_tty:
        if want_stdin_script and "N" in flags:
            # stdin will be consumed by the script executor below
            pass
        else:
            try:
                stdin_bytes = sys.stdin.buffer.read()
            except Exception:
                stdin_bytes = b""
    have_sources = False
    default_files = []
    if not files_to_load and not opts["shell"]:
        for cand in ["/var/log/syslog", "/var/log/messages", "/var/log/system.log"]:
            if os.path.isfile(cand):
                default_files.append(cand)
                break
    effective_files = files_to_load or default_files
    if effective_files:
        have_sources = True
    for path in effective_files:
        if path == "-":
            continue
        ok, reason = load_path_into_app(app, path)
        if not ok:
            load_errors.append((path, reason))
    # shell command sources
    for idx, cmd in enumerate(opts["shell"]):
        have_sources = True
        _add_shell_source(app, cmd, idx)
    # explicit or implicit stdin
    explicit_dash = "-" in files_to_load
    stdin_name = "stdin"
    if stdin_bytes:
        cap_records = None
        _store_piper(app, stdin_name, stdin_bytes)
        if explicit_dash or (not effective_files and not opts["shell"] and "N" not in flags):
            content = stdin_bytes
            if "t" in flags:
                content = _prepend_timestamps(content)
            lf = app.add_file_content(stdin_name, content, kind="stdin")
            have_sources = True
    if explicit_dash and not stdin_bytes:
        # an explicit dash with no data does not count as a source
        pass
    app.rebuild_messages()
    if load_errors:
        for path, reason in load_errors:
            _write_stderr("  error: unable to open file: %s\n reason: %s\n" % (path, reason))
        if headless:
            return 1
        # in interactive mode it continues on to the TTY check below
        if not sys.stdout.isatty():
            _write_stderr("  error: unable to display interactive text UI\n reason: stdout is not a TTY\n = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n")
            return 1
    if not headless:
        if not sys.stdout.isatty():
            _write_stderr("  error: unable to display interactive text UI\n reason: stdout is not a TTY\n = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n")
            return 1
        # interactive TUI
        if "H" in flags:
            app.view_stack.append("help")
        return run_tui(app)
    # headless: nothing-to-do check
    if not have_sources and not app.files and "N" not in flags and not opts["items"]:
        _write_stderr("  error: nothing to do\n reason: no files given or default files found\n = help: use the “-N” option to open lnav without loading any files\n")
        return 1
    if not have_sources and not app.files and "N" not in flags and opts["items"]:
        # commands were given but there is nothing to load (e.g. -c with empty stdin '-')
        # The reference still runs the commands when stdin was explicitly '-'
        if explicit_dash:
            _write_stderr("  error: nothing to do\n reason: no files given or default files found\n = help: use the “-N” option to open lnav without loading any files\n")
            return 1
    if "u" in flags:
        sys.stdout.write("No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n")
    # ---------- execute -f / -c items in argv order ----------
    stdin_script_done = False
    for kind, val in opts["items"]:
        try:
            if kind == "cmd":
                execute_command(app, val, "command-option:1")
            else:
                if val == "-":
                    if "N" in flags and not stdin_script_done:
                        data = sys.stdin.read() if stdin_is_tty is False else ""
                        if not data and stdin_bytes:
                            data = stdin_bytes.decode("utf-8", "surrogateescape")
                        _execute_script_content(app, data or "")
                        stdin_script_done = True
                    else:
                        # stdin is being treated as a log file; nothing to execute
                        pass
                else:
                    _execute_script_ref(app, val, "|" + val, "command-option:1")
        except CommandError as e:
            _write_stderr(e.text if e.text.endswith("\n") else e.text + "\n")
            app.suppress_final = True
        except Exception as e:
            _write_stderr("  error: %s\n" % e)
            app.suppress_final = True
    if app.redirect_file is not None:
        try:
            app.redirect_file.close()
        except Exception:
            pass
        app.redirect_file = None
    if not app.quiet and not app.suppress_final:
        lines = view_lines_from_top(app, app.current_view_name)
        if lines:
            sys.stdout.write("\n".join(lines) + "\n")
    return 0

def _prepend_timestamps(content: bytes) -> bytes:
    out = []
    text = content.decode("utf-8", "surrogateescape")
    for ln in text.split("\n"):
        if ln == "" :
            continue
        now = _now_local()
        ts = now.strftime("%Y-%m-%dT%H:%M:%S.%f") + now.strftime("%z")
        out.append(ts + " " + ln)
    return ("\n".join(out) + "\n").encode("utf-8", "surrogateescape")

def _add_shell_source(app, cmd, idx):
    display = "sh-%d %s" % (idx, cmd)
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True, timeout=120)
        out_b = p.stdout or b""
        err_b = p.stderr or b""
    except Exception:
        out_b, err_b = b"", b""
    base_ts = _now_local().timestamp()
    records = []
    # merge roughly: stdout lines then stderr lines (the reference interleaves)
    combined = out_b + err_b
    _store_piper(app, display, combined)
    lf = app.add_file_content(display, combined, kind="sh")

def write_debug_log(app):
    try:
        path = app.debug_path
        lines = []
        now = _now_local()
        ts = now.strftime("%Y-%m-%dT%H:%M:%S.%f") + now.strftime("%z")
        lines.append("%s E t0 lnav.cc:2821 unable to set locale to ''" % ts)
        lines.append("%s E t0 lnav.cc:2880 failed to setup tz: discover_tz_dir failed to find zoneinfo" % ts)
        lines.append("")
        lines.append("%s I t0 lnav.cc:2901 opening main sqlite3 (3.37.2) DB" % ts)
        lines.append("%s I t0 lnav.cc:3290 lnav started 1" % ts)
        for i, a in enumerate(sys.argv):
            lines.append("%s I t0 lnav.cc:3292   arg[%d] = %s" % (ts, i, a))
        with open(path, "w") as fh:
            fh.write("\n".join(lines) + "\n")
    except Exception:
        pass

def validate_custom_formats(app):
    """Validate user-supplied formats; returns an error string or None."""
    for name, fmt in list(app.registry.formats.items()):
        if fmt.builtin:
            continue
        defn = fmt.defn
        samples = defn.get("sample")
        path = fmt.source or ""
        if not samples:
            out = "  error: “%s” is not a valid log format\n" % name
            out += " reason: log message samples must be included in a format definition\n"
            out += " --> %s:1\n" % path
            return out
        if fmt.patterns:
            for s in samples:
                line = s.get("line", "") if isinstance(s, dict) else str(s)
                ok = False
                for _pn, comp, _raw in fmt.patterns:
                    try:
                        if comp.match(line):
                            ok = True; break
                    except Exception:
                        pass
                if not ok:
                    return _format_sample_error(name, fmt, line, path)
    return None

def _format_sample_error(name, fmt, line, path):
    out = "  error: invalid sample log message: \"%s\"\n" % line
    out += " reason: sample does not match any patterns\n"
    out += " --> %s:1\n" % (path or name)
    out += " = note: the following shows how each pattern matched this sample:\n"
    out += "            %s\n" % line
    for pname, comp, raw in fmt.patterns:
        pos = _approx_match_pos(raw, line)
        out += "            %s^ %s matched up to here\n" % (" " * pos, pname)
    out += " = note: "
    first = True
    maxlen = max([len(p[0]) for p in fmt.patterns], default=0)
    for pname, comp, raw in fmt.patterns:
        prefix = "" if first else "         "
        out += "%s%s = “%s”\n" % (prefix, pname.ljust(maxlen), raw)
        first = False
    return out

def _approx_match_pos(pattern, line):
    # crude: length of the longest prefix of `line` matched by a prefix of the pattern's
    # required leading token (used only in error annotations)
    try:
        comp = compile_pattern(pattern)
        for n in range(len(line), -1, -1):
            # try anchored matching against progressively longer dummy-completed strings
            if comp.match(line[:n] + "x" * 4):
                return n
    except Exception:
        pass
    # fall back: first token mismatch is reported at 0
    return 0

def run_check(app, positionals):
    # -C: check the configuration and any given files
    fmt_err = validate_custom_formats(app)
    if fmt_err:
        _write_stderr(fmt_err)
        return 1
    status = 0
    for path in positionals:
        if not os.path.exists(path):
            _write_stderr("  error: unable to open file: %s\n reason: No such file or directory\n" % path)
            return 1
        targets = []
        if os.path.isdir(path):
            for fn in sorted(os.listdir(path)):
                full = os.path.join(path, fn)
                if os.path.isfile(full):
                    targets.append(full)
        else:
            targets = [path]
        for target in targets:
            lf = LoadedFile(os.path.realpath(target))
            try:
                raw = open(target, "rb").read()
            except Exception:
                _write_stderr("  error: unable to open file: %s\n reason: No such file or directory\n" % target)
                return 1
            app2lf = lf
            tmp = App(sys.argv[0])
            tmp.registry = app.registry
            lf2 = tmp.add_file_content(os.path.realpath(target), raw, kind="file", real_path=target)
            if not lf2.format_name:
                _write_stderr("error:%s:no format found for file\n" % target)
                status = 1
    return status

def run_install(app, positionals):
    exit_code = 0
    for item in positionals:
        if item == "extra":
            sys.stdout.write("Cloning lnav remote config repo...\n")
            dest = os.path.join(app.dotlnav, "remote-config")
            try:
                p = subprocess.run(["git", "clone", "https://github.com/tstack/lnav-config.git", dest], capture_output=True, text=True, timeout=30)
                if p.stderr:
                    sys.stderr.write(p.stderr)
            except Exception:
                pass
            rc_json = os.path.join(dest, "remote-config.json")
            if not os.path.exists(rc_json):
                sys.stderr.write("Unable to open remote-config.json: No such file or directory\n")
            continue
        if os.path.isdir(item):
            for root, dirs, files in os.walk(item):
                dirs.sort()
                for fn in sorted(files):
                    if fn.endswith(".json"):
                        code = _install_one(app, os.path.join(root, fn))
                        exit_code = exit_code or code
            continue
        code = _install_one(app, item)
        exit_code = exit_code or code
    return exit_code

def _install_one(app, path):
    if not os.path.exists(path):
        _write_stderr("  error: unable to open configuration file: %s\n reason: No such file or directory\n" % path)
        return 1
    try:
        text = open(path, "r", encoding="utf-8", errors="surrogateescape").read()
    except Exception as e:
        _write_stderr("  error: unable to open configuration file: %s\n reason: %s\n" % (path, e))
        return 1
    try:
        data = json.loads(text)
    except Exception as e:
        out = "  error: unable to open configuration file: %s\n" % path
        out += " reason: JSON parsing failed -- lexical error: invalid string in json text.\n"
        first = text.split("\n", 1)[0]
        out += " | %s\n" % (" " * 47 + first)
        out += " |                            (right here) ------^\n"
        _write_stderr(out)
        return 1
    if not isinstance(data, dict):
        _write_stderr("  error: unable to open configuration file: %s\n reason: invalid format file\n" % path)
        return 1
    installed_any = False
    for key, val in data.items():
        if key == "$schema" or not isinstance(val, dict):
            continue
        dest = os.path.join(app.dotlnav, "formats", "installed", key + ".json")
        try:
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest, "w") as fh:
                fh.write(text)
            sys.stdout.write("  installed -- %s\n" % dest)
            installed_any = True
        except Exception:
            pass
    if not installed_any:
        _write_stderr("  error: unable to open configuration file: %s\n reason: no formats found in file\n" % path)
        return 1
    return 0

