def parse_main_args(argv):
    """Returns (opts, positionals). Raises CliExit with the proper code/output."""
    opts = {"flags": set(), "commands": [], "debug": [], "shell": [], "scripts": [], "include": [], "since": [], "until": [], "items": []}
    positionals = []
    unknowns = []
    missing = []
    i = 0
    after_dd = False
    args = argv
    while i < len(args):
        tok = args[i]
        if after_dd:
            positionals.append(tok); i += 1; continue
        if tok == "--":
            after_dd = True; i += 1; continue
        if tok.startswith("--"):
            if "=" in tok:
                name, val = tok.split("=", 1)
                has_val = True
            else:
                name, val, has_val = tok, None, False
            if name in MAIN_LONG:
                ch = MAIN_LONG[name]
                if ch in ("h", "V"):
                    opts["flags"].add(ch)
                else:
                    if not has_val:
                        if i + 1 < len(args):
                            val = args[i + 1]; i += 1
                        else:
                            missing.append(MAIN_VALUE_OPTS[ch][0]); i += 1; continue
                    opts[MAIN_VALUE_OPTS[ch][1]].append(val)
                    if ch == "S":
                        opts["items"].append(("since", val))
                i += 1; continue
            unknowns.append(tok); i += 1; continue
        if tok.startswith("-") and tok != "-" and len(tok) > 1 and not tok[1].isdigit():
            # bundled short options
            j = 1
            consumed_value = False
            while j < len(tok):
                ch = tok[j]
                if ch == "i":
                    opts["flags"].add("i"); j += 1; continue
                if ch in MAIN_FLAGS:
                    opts["flags"].add(ch); j += 1; continue
                if ch in MAIN_VALUE_OPTS:
                    rest = tok[j + 1:]
                    if rest.startswith(":"):
                        rest = rest[1:]
                    if rest != "":
                        val = rest
                    elif i + 1 < len(args):
                        val = args[i + 1]; i += 1
                    else:
                        missing.append(MAIN_VALUE_OPTS[ch][0])
                        val = None
                    if val is not None:
                        key = MAIN_VALUE_OPTS[ch][1]
                        opts[key].append(val)
                        if key == "commands":
                            opts["items"].append(("cmd", val))
                        elif key == "scripts":
                            opts["items"].append(("file", val))
                    consumed_value = True
                    break
                # unknown
                unknowns.append(tok if j == 1 else "-" + tok[j:])
                break
            i += 1; continue
        positionals.append(tok); i += 1
    return opts, positionals, unknowns, missing

def _main_cli_error(reason, code=109):
    sys.stderr.write("  error: invalid command-line arguments\n reason: %s\n" % reason)
    raise CliExit(code)

def run_main(argv):
    argv0 = argv[0] if argv else "./executable"
    args = argv[1:]
    app = App(argv0)
    # parse
    try:
        opts, positionals, unknowns, missing = parse_main_args(args)
    except CliExit as e:
        return e.code
    flags = opts["flags"]
    # -c validation happens before other checks (observed)
    for cmd in opts["commands"]:
        if cmd == "":
            _write_stderr("  error: invalid command-line arguments\n reason: -c: empty commands are not allowed\n")
            return 105
        if cmd[0] not in ":;|/":
            out = "  error: invalid value for “-c” option\n"
            out += " --> command-line argument\n"
            out += " |  %s\n" % ("-c " + cmd).ljust(40)
            out += " |     ^ command type prefix is missing    \n"
            out += " = help: command arguments must start with one of the following symbols to denote the type of command:\n"
            out += "            : - an lnav command   (e.g. :goto 42)\n"
            out += "            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)\n"
            out += "            | - an lnav script    (e.g. |rename-stdin foo)\n"
            _write_stderr(out)
            return 105
    if missing:
        _write_stderr("  error: invalid command-line arguments\n reason: %s\n" % missing[0])
        return 114
    # -I validation (after missing, before help)
    for inc in opts["include"]:
        if not os.path.isdir(inc):
            _write_stderr("  error: invalid command-line arguments\n reason: -I: Directory does not exist: %s\n" % inc)
            return 105
    app.include_dirs = list(opts["include"])
    # version / help
    if "V" in flags:
        sys.stdout.write(VERSION + "\n")
        return 0
    if "h" in flags:
        # help needs paths, but does not create ~/.lnav
        _print_main_help(app, argv0 if "/" in argv0 or True else app.bin_path)
        return 0
    if unknowns:
        rev = list(reversed(unknowns))
        if len(rev) == 1:
            _write_stderr("  error: invalid command-line arguments\n reason: The following argument was not expected: %s\n" % rev[0])
        else:
            _write_stderr("  error: invalid command-line arguments\n reason: The following arguments were not expected: %s\n" % " ".join(rev))
