def _prepend_timestamps(content: bytes) -> bytes:
    out = []
    text = content.decode("utf-8", "surrogateescape")
    for ln in text.split("\n"):
        if ln == "" :
            continue
        now = _now_local()
        ts = now.strftime("%Y-%m-%dT%H:%M:%S.%f") + now.strftime("%z")
        out.append(ts + " " + ln)
    return ("\n".join(out) + "\n").encode("utf-8", "surrogateescape")

