def validate_custom_formats(app):
    """Validate user-supplied formats; returns an error string or None."""
    for name, fmt in list(app.registry.formats.items()):
        if fmt.builtin:
            continue
        defn = fmt.defn
        samples = defn.get("sample")
        path = fmt.source or ""
        if not samples:
            out = "  error: “%s” is not a valid log format\n" % name
            out += " reason: log message samples must be included in a format definition\n"
            out += " --> %s:1\n" % path
            return out
        if fmt.patterns:
            for s in samples:
                line = s.get("line", "") if isinstance(s, dict) else str(s)
                ok = False
                for _pn, comp, _raw in fmt.patterns:
                    try:
                        if comp.match(line):
                            ok = True; break
                    except Exception:
                        pass
                if not ok:
                    return _format_sample_error(name, fmt, line, path)
    return None

def _format_sample_error(name, fmt, line, path):
    out = "  error: invalid sample log message: \"%s\"\n" % line
    out += " reason: sample does not match any patterns\n"
    out += " --> %s:1\n" % (path or name)
    out += " = note: the following shows how each pattern matched this sample:\n"
    out += "            %s\n" % line
    for pname, comp, raw in fmt.patterns:
        pos = _approx_match_pos(raw, line)
        out += "            %s^ %s matched up to here\n" % (" " * pos, pname)
    out += " = note: "
    first = True
    maxlen = max([len(p[0]) for p in fmt.patterns], default=0)
    for pname, comp, raw in fmt.patterns:
        prefix = "" if first else "         "
        out += "%s%s = “%s”\n" % (prefix, pname.ljust(maxlen), raw)
        first = False
    return out

def _approx_match_pos(pattern, line):
    # crude: length of the longest prefix of `line` matched by a prefix of the pattern's
    # required leading token (used only in error annotations)
    try:
        comp = compile_pattern(pattern)
        for n in range(len(line), -1, -1):
            # try anchored matching against progressively longer dummy-completed strings
            if comp.match(line[:n] + "x" * 4):
                return n
    except Exception:
        pass
    # fall back: first token mismatch is reported at 0
    return 0

