            txt += "          • %s: %s\n" % (nm, desc)
        _write_stderr(txt)
        return 1
    head = path[0]
    if head == "apps":
        if len(path) == 1:
            _write_stderr("  error: expecting an operation related to lnav apps\n = help: the available operations are:\n          • create: create a new app\n")
            return 1
        return _mgmt_apps_create(app, getvals(node))
    if head == "config":
        if len(path) == 1:
            _write_stderr("  error: expecting an operation related to lnav configuration\n = help: the available operations are:\n          • get: print the current configuration\n          • blame: print the configuration options and their source\n          • file-options: print the options applied to specific files\n")
            return 1
        sub = path[1]
        if sub == "get":
            cfg_err = _check_config_errors(app)
            if cfg_err:
                _write_stderr(cfg_err)
                return 1
            sys.stdout.write(_json_pretty(app.config) + "\n")
            return 0
        if sub == "blame":
            sys.stdout.write(_config_blame(app))
            return 0
        if sub == "file-options":
            vals = getvals(node)
            if not vals:
                _write_stderr("  error: Expecting a file path to check for options\n")
                return 1
            _write_stderr("  info: no options found for file: %s\n = help: Use the :set-file-timezone command to set the zone for messages in files that do not include a zone in the timestamp\n" % vals[0])
            return 0
    if head == "piper":
        if len(path) == 1:
            _write_stderr("  error: expecting an operation related to piper storage\n = help: the available operations are:\n          • list: print the available piper captures\n          • clean: remove all piper captures\n")
            return 1
        if path[1] == "list":
            return _mgmt_piper_list(app)
        if path[1] == "clean":
            import shutil
            try:
                shutil.rmtree(os.path.join(app.work_dir, "piper"), ignore_errors=True)
            except Exception:
                pass
            return 0
    if head == "crash":
        if len(path) == 1:
            _write_stderr("  error: expecting an operation related to crash logs\n = help: the available operations are:\n          • upload: upload crash logs\n")
            return 1
        return _mgmt_crash_upload(app)
    if head == "regex101":
        if len(path) == 1:
            _write_stderr("  error: expecting an operation related to the regex101.com integration\n = help: the available operations are:\n          • list: list the log format regular expression linked to entries on regex101.com\n          • import: create a new format from a regular expression on regex101.com\n")
            return 1
        if path[1] == "list":
            sys.stdout.write("  no regex101 entries found\n")
            return 0
        if path[1] == "import":
            vals = getvals(node)
            if not vals:
                _write_stderr("  error: expecting a regex101.com URL to import\n")
                return 1
            if len(vals) < 2:
                _write_stderr("  error: expecting a name for the new format\n")
                return 1
            url = vals[0]
            m = re.search(r'regex101\.com/r/([^/]+)', url)
