            return 1
    if head == "format":
        return _mgmt_format(app, node, path, posvals)
    return 1

def _check_config_errors(app):
    for kind, path, err in getattr(app, "format_errors", []):
        if kind == "config":
            try:
                text = open(path).read()
            except Exception:
                text = ""
            first = text.split("\n", 1)[0]
            out = "  error: invalid JSON\n"
            out += " --> %s:1\n" % path
            out += " | lexical error: invalid char in json text.      \n"
            out += " | %s%s\n" % (" " * 39, first)
            out += " |                      (right here) ------^      \n"
            return out
    return None

def _config_blame(app):
    base = data_text("blame_b64")
    # overlay any user-config leaf paths
    try:
        lines = {}
        for ln in base.splitlines():
            if " -> " in ln:
                k, v = ln.split(" -> ", 1)
                lines[k] = v
        for path in getattr(app, "config_sources", []):
            try:
                data = json.load(open(path))
            except Exception:
                continue
            def walk(obj, prefix):
                if isinstance(obj, dict):
                    for k, v in obj.items():
                        walk(v, prefix + "/" + str(k))
                else:
                    lines[prefix] = "%s:%d" % (os.path.basename(path), 1)
            stripped = {k: v for k, v in data.items() if k != "$schema"}
            walk(stripped, "")
        out = "".join("%s -> %s\n" % (k, lines[k]) for k in sorted(lines))
        return out
    except Exception:
        return base

def _mgmt_apps_create(app, vals):
