def _humanize_relative(ts_epoch, now_epoch):
    diff = now_epoch - ts_epoch
    if diff < 60:
        return "just now"
    minutes = int(diff // 60)
    if minutes < 60:
        return "%d minute%s ago" % (minutes, "s" if minutes != 1 else "")
    hours = int(diff // 3600)
    if hours < 24:
        return "%d hour%s ago" % (hours, "s" if hours != 1 else "")
    days = int(diff // 86400)
    if days < 7:
        return "%d day%s ago" % (days, "s" if days != 1 else "")
    weeks = int(days // 7)
    if weeks < 5:
        return "%d week%s ago" % (weeks, "s" if weeks != 1 else "")
    months = int(days // 30)
    if months < 12:
        return "%d month%s ago" % (max(1, months), "s" if months != 1 else "")
    years = int(days // 365)
    return "%d year%s ago" % (years, "s" if years != 1 else "")

def _humanize_disk(size, total=False):
    if total:
        if size < 1000:
            return "%dB" % size
        for unit in ("KB", "MB", "GB", "TB"):
            size_f = size / 1000.0
            if size_f < 1000:
                return "%.1f%s" % (size_f, unit)
            size = size_f
        return "%.1fPB" % size
    if size < 1000:
        return "%.1f B" % float(size)
    val = float(size)
    for unit in ("KB", "MB", "GB", "TB"):
        val /= 1000.0
        if val < 1000:
            return "%.1f%s" % (val, unit)
    return "%.1fPB" % val

def _mgmt_piper_list(app):
    pdir = os.path.join(app.work_dir, "piper")
    captures = []
    total = 0
    if os.path.isdir(pdir):
        for entry in sorted(os.listdir(pdir)):
            full = os.path.join(pdir, entry)
            if not os.path.isdir(full) or not entry.startswith("p-"):
                continue
            for fn in os.listdir(full):
                if not fn.startswith("out."):
                    continue
                header, _recs, _plain = _read_piper_bytes(os.path.join(full, fn))
                try:
                    fsize = os.path.getsize(os.path.join(full, fn))
                except Exception:
                    fsize = 0
                # the reported size excludes the header JSON blob
                hlen = 0
                try:
                    data_len = fsize
                    # re-read small prefix via header length stored in the file
                    with open(os.path.join(full, fn), "rb") as fh:
                        prefix = fh.read(8)
                    hlen = int.from_bytes(prefix[6:8], "big")
                except Exception:
                    pass
                size = data_len - hlen
                total += max(0, size)
                captures.append({"id": entry, "name": (header or {}).get("name", "stdin"), "ctime": (header or {}).get("ctime", ""), "cwd": (header or {}).get("cwd", ""), "env": (header or {}).get("env", {}), "size": max(0, size)})
    try:
        captures.sort(key=lambda c: c["ctime"])
    except Exception:
        pass
    verbosity = getattr(app, "mgmt_verbosity", 1)
    if not captures:
        if verbosity > 0:
            _write_stderr("  info: no piper captures were found in:\n\t%s\n = help: You can create a capture by piping data into lnav or using the “:sh” command\n" % pdir)
        return 0
    now = _now_local()
    for c in captures:
        tstamp = None
        try:
            tstamp = datetime.datetime.strptime(c["ctime"], "%Y-%m-%dT%H:%M:%S.%f").replace(tzinfo=now.tzinfo)
            rel = _humanize_relative(tstamp.timestamp(), now.timestamp())
        except Exception:
            rel = "just now"
        line = "%18s  piper://%s   %-9s “%s”\n" % (rel, c["id"], _humanize_disk(c["size"]), c["name"])
        sys.stdout.write(line)
        if verbosity >= 2:
            ind = " " * 23
            sys.stdout.write("%scwd: %s\n" % (ind, c["cwd"]))
            env_items = list((c["env"] or {}).items())
            for i, (k, v) in enumerate(env_items):
                if i == 0:
                    sys.stdout.write("%senv: %s=%s\n" % (ind, k, v))
                else:
                    sys.stdout.write("%s     %s=%s\n" % (ind, k, v))
    if verbosity > 0:
        _write_stderr("  info: the following piper captures were found in:\n\t%s\n = note: The captures currently consume %s of disk space.  File sizes include associated metadata.\n = help: You can reopen a capture by passing the piper URL to lnav\n" % (pdir, _humanize_disk(total, total=True)))
    return 0

def _mgmt_crash_upload(app):
    cdir = os.path.join(app.dotlnav, "crash")
