        self.positionals = positionals or []  # (name, desc)
        self.subcommands = subcommands or {}
        self.action = action

def _mgmt_tree(app):
    fmt_node = MgmtNode("format", "perform operations on log file formats", positionals=[("format_name", "the name of the format")])
    regex101_node = MgmtNode("regex101", "use regex101.com to edit this regular expression", subcommands={
