        "source": MgmtNode("source", "print the path of the first source file containing this format"),
        "sources": MgmtNode("sources", "print the paths of all source files containing this format"),
        "regex": regex_node,
    }
    root = MgmtNode("", "", subcommands={
        "apps": MgmtNode("apps", "manage lnav apps", subcommands={"create": MgmtNode("create", "create a new app", positionals=[("name", "name of the app")])}),
        "config": MgmtNode("config", "perform operations on the lnav configuration", subcommands={
