            "list": MgmtNode("list", "list the log format regular expression linked to entries on regex101.com"),
            "import": MgmtNode("import", "create a new format from a regular expression on regex101.com", positionals=[("url", "The regex101.com url to construct a log format from"), ("name", "The name for the log format"), ("regex-name", "The name for the new regex")]),
        }),
        "crash": MgmtNode("crash", "manage crash logs", subcommands={"upload": MgmtNode("upload", "upload crash logs")}),
    })
    return root

def _mgmt_help(app, argv0, node, path):
    lines = []
    if not path:
        lines.append("The Logfile Navigator")
        usage = "Usage: %s [OPTIONS] [SUBCOMMAND]" % argv0
    else:
        lines.append(node.desc)
        usage = "Usage: %s %s [OPTIONS]" % (argv0, " ".join(path))
        for pname, _pd in node.positionals:
            usage += " [%s]" % pname
        if node.subcommands:
            usage += " [SUBCOMMAND]"
    lines.append(usage)
    lines.append("")
    if node.positionals:
        lines.append("Positionals:")
        for pname, pdesc in node.positionals:
            label = "%s TEXT" % pname
            lines.append("  %-28s%s" % (label, pdesc))
        lines.append("")
    lines.append("Options:")
    if not path:
        opts = [("-h,--help", "Print this help message and exit"), ("-d FILE", "Write debug messages to the given file."), ("-D", "Enable debugging of notcurses"), ("-I TEXT:DIR ...", "include paths"), ("-q{0},-v{2}", "Control the verbosity"), ("-V,--version", "Display program version information and exit"), ("-m", "Switch to the management CLI mode.")]
        for o, d in opts:
            lines.append("  %-28s%s" % (o, d))
    else:
        lines.append("  %-28s%s" % ("-h,--help", "Print this help message and exit"))
    if node.subcommands:
        lines.append("")
        lines.append("Subcommands:")
        for sname, snode in node.subcommands.items():
            lines.append("  %-28s%s" % (sname, snode.desc))
    lines.append("")
    lines.append("Version: %s" % VERSION)
    lines.append("")
    return "\n".join(lines) + "\n"

def run_mgmt(argv):
    argv0 = argv[0]
    args = argv[2:] if len(argv) > 2 else []  # skip program and -m
    app = App(argv0)
    root = _mgmt_tree(app)
    node = root
    path = []
    posvals = {}  # id(node) -> [values]
    def vals_for(n):
        return posvals.setdefault(id(n), [])
    help_flag = False
    version_flag = False
    unknowns = []
    missing = []
    verbosity = 1
    include_dirs = []
    debug_file = None
    after_dd = False
    i = 0
    while i < len(args):
        tok = args[i]
        if after_dd:
            v = vals_for(node)
            if len(v) < len(node.positionals):
                v.append(tok)
            else:
                unknowns.append(tok)
            i += 1; continue
        if tok == "--":
            if not path:
                # reference: rest is ignored for operation purposes
                break
            after_dd = True; i += 1; continue
        # subcommand?
        if node.subcommands and tok in node.subcommands and not tok.startswith("-"):
            node = node.subcommands[tok]
            path.append(tok)
            i += 1; continue
        # help flag anywhere
        if tok in ("-h", "--help") or tok.startswith("--help="):
            help_flag = True; i += 1; continue
        if node is root:
            # global options, with bundling
            if tok.startswith("--"):
                if tok == "--version":
                    version_flag = True; i += 1; continue
                if tok.startswith("--version="):
                    version_flag = True; i += 1; continue
                unknowns.append(tok); i += 1; continue
            if tok.startswith("-") and tok != "-" and len(tok) > 1:
                j = 1; ok = True
                while j < len(tok):
                    ch = tok[j]
                    if ch == "h":
                        help_flag = True; j += 1; continue
                    if ch == "V":
                        version_flag = True; j += 1; continue
                    if ch == "D":
                        j += 1; continue
                    if ch == "m":
                        j += 1; continue
                    if ch == "q":
                        verbosity = 0; j += 1; continue
                    if ch == "v":
                        verbosity = 2; j += 1; continue
                    if ch in ("d", "I"):
                        rest = tok[j + 1:]
                        if rest.startswith(":"):
                            rest = rest[1:]
                        if rest:
                            val = rest
                        elif i + 1 < len(args):
                            val = args[i + 1]; i += 1
                        else:
                            missing.append("-d: 1 required FILE missing" if ch == "d" else "-I: 1 required TEXT:DIR missing")
                            val = None
                        if val is not None:
                            if ch == "d":
                                debug_file = val
                            else:
                                include_dirs.append(val)
                        break
                    unknowns.append(tok if j == 1 else "-" + tok[j:])
                    ok = False
                    break
                i += 1; continue
            # a positional at the root is unexpected (operations are subcommands)
            unknowns.append(tok); i += 1; continue
        # node != root
        if tok.startswith("-") and tok != "-":
            unknowns.append(tok); i += 1; continue
        v = vals_for(node)
        if len(v) < len(node.positionals):
            v.append(tok); i += 1; continue
        unknowns.append(tok); i += 1
    app.include_dirs = include_dirs
    # checks in order
    if missing:
        _write_stderr("  error: invalid command-line arguments\n reason: %s\n" % missing[0])
        return 114
    for inc in include_dirs:
        if not os.path.isdir(inc):
            _write_stderr("  error: invalid command-line arguments\n reason: -I: Directory does not exist: %s\n" % inc)
            return 105
    if version_flag:
        sys.stdout.write(VERSION + "\n")
        return 0
    if help_flag:
        sys.stdout.write(_mgmt_help(app, argv0, node, path))
        return 0
    if unknowns:
        rev = list(reversed(unknowns))
        if len(rev) == 1:
            _write_stderr("  error: invalid command-line arguments\n reason: The following argument was not expected: %s\n" % rev[0])
        else:
            _write_stderr("  error: invalid command-line arguments\n reason: The following arguments were not expected: %s\n" % " ".join(rev))
        return 109
    # startup
    app.registry = get_registry(app.include_dirs, app.dotlnav)
    if debug_file:
        app.debug_path = debug_file
        write_debug_log(app)
    app.init_dirs()
    app.load_config()
    # verbosity affects piper listing details / quiet info
    app.mgmt_verbosity = verbosity
    return _mgmt_execute(app, node, path, posvals)

