def _humanize_relative(ts_epoch, now_epoch):
    diff = now_epoch - ts_epoch
    if diff < 60:
        return "just now"
    minutes = int(diff // 60)
    if minutes < 60:
        return "%d minute%s ago" % (minutes, "s" if minutes != 1 else "")
    hours = int(diff // 3600)
    if hours < 24:
        return "%d hour%s ago" % (hours, "s" if hours != 1 else "")
    days = int(diff // 86400)
    if days < 7:
        return "%d day%s ago" % (days, "s" if days != 1 else "")
    weeks = int(days // 7)
    if weeks < 5:
        return "%d week%s ago" % (weeks, "s" if weeks != 1 else "")
    months = int(days // 30)
    if months < 12:
        return "%d month%s ago" % (max(1, months), "s" if months != 1 else "")
    years = int(days // 365)
    return "%d year%s ago" % (years, "s" if years != 1 else "")

def _humanize_disk(size, total=False):
    if total:
        if size < 1000:
            return "%dB" % size
        for unit in ("KB", "MB", "GB", "TB"):
            size_f = size / 1000.0
            if size_f < 1000:
                return "%.1f%s" % (size_f, unit)
            size = size_f
        return "%.1fPB" % size
    if size < 1000:
        return "%.1f B" % float(size)
    val = float(size)
    for unit in ("KB", "MB", "GB", "TB"):
        val /= 1000.0
        if val < 1000:
            return "%.1f%s" % (val, unit)
    return "%.1fPB" % val

