                    sys.stderr.write("  test file matched format pattern %s\n --> %s:1\n | %s\n" % (pname, path, line))
                    return 0
            except Exception:
                pass
    _write_stderr(_format_test_failure(fmt_name, fmt, line, path))
    return 1

def _format_test_failure(fmt_name, fmt, line, path):
    patterns = fmt.patterns if fmt else []
    out = "  error: invalid sample log message: \"%s\"\n" % line
    out += " reason: sample does not match any patterns\n"
    out += " --> %s:1\n" % path
    out += " = note: the following shows how each pattern matched this sample:\n"
    out += "            %s\n" % line
    # only show the patterns that matched furthest (as the reference does):
    # it lists every pattern with its progress position (all of them, sorted by name)
    sorted_patterns = sorted(patterns, key=lambda p: p[0])
    for pname, comp, raw in sorted_patterns:
        pos = _approx_match_pos(raw, line)
        out += "            %s^ %s matched up to here\n" % (" " * pos, pname)
    if sorted_patterns:
        maxlen = max(len(p[0]) for p in sorted_patterns)
        out += " = note: "
        for i, (pname, comp, raw) in enumerate(sorted_patterns):
            prefix = "" if i == 0 else "         "
            out += "%s%s = “%s”\n" % (prefix, pname.ljust(maxlen), raw)
    else:
        out += " = note: no patterns defined\n"
    return out

def _mgmt_format_regex(app, fmt_name, fmt, node, path, posvals):
    vals = posvals.get(id(node), [])
    regex_name = vals[0] if vals else ""
    pattern_names = [p[0] for p in fmt.patterns] if fmt else []
    if not regex_name:
        if fmt_name in INTERNAL_FORMATS:
            _write_stderr("  error: “%s” is an internal format that is not defined in a configuration file\n" % fmt_name)
            return 1
        display = sorted(pattern_names)
        txt = "  error: expecting a regex name to operate on\n"
        txt += " = note: the available regexes are: " + ", ".join([""] + display) + "\n"
        _write_stderr(txt)
        return 1
    if regex_name not in pattern_names:
        _write_stderr("  error: unknown regex: %s\n" % regex_name)
        return 1
    if len(path) < 3:
        txt = "  error: expecting an operation to perform on the %s regular expression\n" % regex_name
        txt += " = help: the available subcommands are:\n"
        txt += "          • regex101: use regex101.com to edit this regular expression\n"
        _write_stderr(txt)
        return 1
    # path[2] == regex101
    if len(path) < 4:
        txt = "  error: expecting an operation to perform on the %s regex using regex101.com\n" % regex_name
        txt += " = help: the available subcommands are:\n"
        txt += "          • push: create/update an entry for this regex on regex101.com\n"
        txt += "          • pull: create a patch format file for this regular expression based on the entry in regex101.com\n"
        txt += "          • delete: delete the entry regex101.com that was created by a push operation\n"
        _write_stderr(txt)
        return 1
    sub = path[3]
    if sub == "push":
        _write_stderr("Attempting to unwrap an error Result\n")
        return 1
    if sub == "pull":
        _write_stderr("  error: regex “%s” of format “%s” has not been pushed to regex101.com\n = help: use the “push” subcommand to create the regex on regex101.com for easy editing\n" % (regex_name, fmt_name))
        return 1
    if sub == "delete":
        _write_stderr("  error: no regex101 entry for %s/%s\n" % (fmt_name, regex_name))
        return 1
    return 1

