# TUI (curses)

def run_tui(app):
    try:
        import curses
    except Exception:
        _write_stderr("  error: unable to display interactive text UI\n reason: stdout is not a TTY\n = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n")
        return 1
    def _main(stdscr):
        curses.curs_set(0)
        try:
            stdscr.keypad(True)
        except Exception:
            pass
        show_help = app.current_view_name == "help"
        while True:
            stdscr.erase()
            height, width = stdscr.getmaxyx()
            if show_help:
                lines = view_lines(app, "help")
                for i, ln in enumerate(lines[:max(0, height - 1)]):
                    try:
                        stdscr.addstr(i, 0, ln[:max(0, width - 1)])
                    except Exception:
                        pass
            else:
                # header
                clock = _now_local().strftime("%Y-%m-%dT%H:%M:%S") + " UTC"
                try:
                    stdscr.addstr(0, 0, " " + clock)
                    stdscr.addstr(1, 0, " LOG ▼")
                except Exception:
                    pass
                msgs = filtered_messages(app)
                top_sel = app.views["log"].get("selection", 0) or 0
                # keep the selection visible
                body_lines = []
                for m in msgs:
                    body_lines.extend(message_display_lines(app, m))
                start = max(0, min(top_sel, max(0, len(body_lines) - max(1, height - 4))))
                for i in range(start, min(len(body_lines), start + max(0, height - 4))):
                    try:
                        stdscr.addstr(2 + (i - start), 0, body_lines[i][:max(0, width - 1)])
                    except Exception:
                        pass
                # bottom status
                try:
                    percent = 100 if not body_lines else int(round(100.0 * (min(start + max(0, height - 4), len(body_lines))) / len(body_lines))) if body_lines else 100
                    stdscr.addstr(height - 2, 0, " Files :: Text Filters ::")
                    stdscr.addstr(height - 1, 0, " L%d        %d%%" % (top_sel, percent))
                except Exception:
                    pass
            stdscr.refresh()
            try:
                ch = stdscr.getch()
            except Exception:
                return 0
            if ch in (ord('q'),):
                if show_help:
                    show_help = False
                else:
                    return 0
            elif ch == ord('?'):
                show_help = not show_help
            elif ch in (ord('j'), curses.KEY_DOWN):
                if app.messages:
                    cur = app.views["log"].get("selection", 0) or 0
                    cur = min(cur + 1, len(app.messages) - 1)
                    app.views["log"]["selection"] = cur; app.views["log"]["top"] = cur
            elif ch in (ord('k'), curses.KEY_UP):
                cur = app.views["log"].get("selection", 0) or 0
                cur = max(cur - 1, 0)
                app.views["log"]["selection"] = cur; app.views["log"]["top"] = cur
            elif ch == ord('g'):
                app.views["log"]["selection"] = 0; app.views["log"]["top"] = 0
            elif ch == ord('G'):
                if app.messages:
                    app.views["log"]["selection"] = len(app.messages) - 1; app.views["log"]["top"] = len(app.messages) - 1
            elif ch == ord('t'):
                if app.current_view_name == "text" and len(app.view_stack) > 1:
                    app.view_stack.pop()
                elif "text" not in app.view_stack:
                    app.view_stack.append("text")
                    return _tui_text_view(stdscr_holder, app)
            elif ch == 27:
                pass
    stdscr_holder = {}
    try:
        return curses.wrapper(lambda s: _tui_loop(app, s))
    except CliExit as e:
        return e.code
    except Exception:
        return 0

def _tui_loop(app, stdscr):
    import curses
    try:
        curses.curs_set(0)
    except Exception:
        pass
    try:
        stdscr.keypad(True)
    except Exception:
        pass
    # Initial selection: follow to the last message like the reference tail mode
    if app.messages:
        app.views["log"]["selection"] = len(app.messages) - 1
    show_help = ("help" in app.view_stack)
    view = "log" if not show_help else "help"
    while True:
        stdscr.erase()
        height, width = stdscr.getmaxyx()
        try:
            if view == "help":
                lines = view_lines(app, "help")
                for i, ln in enumerate(lines[:max(0, height - 1)]):
                    stdscr.addstr(i, 0, ln[:max(0, width - 1)])
            elif view == "text":
                lines = view_lines(app, "text")
                for i, ln in enumerate(lines[:max(0, height - 3)]):
                    stdscr.addstr(2 + i, 0, ln[:max(0, width - 1)])
                stdscr.addstr(0, 0, " " + _now_local().strftime("%Y-%m-%dT%H:%M:%S") + " UTC")
                stdscr.addstr(1, 0, " TEXT ▼")
            else:
                clock = _now_local().strftime("%Y-%m-%dT%H:%M:%S") + " UTC"
                stdscr.addstr(0, 0, " " + clock + "                                    Press ` to focus on the breadcrumb bar")
                # breadcrumb
                msg = app._focused_message()
                crumb = " LOG ▼"
                if msg is not None and msg.timestamp:
                    crumb += "  ：%s ：%s ：%s[%d] ：" % (msg.timestamp.strftime("%Y-%m-%dT%H:%M:%S.%f"), msg.format_name, os.path.basename(msg.file.display_path) if msg.file else "", msg.global_index)
                stdscr.addstr(1, 0, crumb[:max(0, width - 1)])
                msgs = filtered_messages(app)
                body_lines = []
                for m in msgs:
                    body_lines.extend(message_display_lines(app, m))
                    body_lines.extend(_metadata_lines(m))
                sel = app.views["log"].get("selection", 0) or 0
                # compute a start so the selected message is visible
                start = 0
                row_of_sel = 0
                acc = 0
                for m in msgs:
                    if m.global_index == sel:
                        row_of_sel = acc
                        break
                    acc += len(message_display_lines(app, m)) + len(_metadata_lines(m))
                visible = max(1, height - 4)
                if row_of_sel >= visible:
                    start = row_of_sel - visible + 1
                for i in range(start, min(len(body_lines), start + visible)):
                    stdscr.addstr(2 + (i - start), 0, body_lines[i][:max(0, width - 1)])
                stdscr.addstr(2 + visible, 0, "") if height > 4 else None
                stdscr.addstr(height - 2, 0, " Files :: Text Filters ::                                                         Press TAB to edit")
                pct = 100 if not body_lines else int(round(100.0 * min(len(body_lines), start + visible) / max(1, len(body_lines))))
                stdscr.addstr(height - 1, 0, " L%d        %d%%                                                                         ?:View Help" % (sel, pct))
        except Exception:
            pass
        stdscr.refresh()
        try:
            ch = stdscr.getch()
        except Exception:
            return 0
        if ch == ord('q'):
            if view == "help":
                view = "log"
            elif view == "text":
                view = "log"
            else:
                return 0
        elif ch == ord('?'):
            view = "help" if view != "help" else "log"
        elif ch == ord('t'):
            view = "text" if view != "text" else "log"
        elif ch in (ord('j'),) or ch == 258:
            if app.messages:
                cur = app.views["log"].get("selection", 0) or 0
                app.views["log"]["selection"] = min(cur + 1, len(app.messages) - 1)
        elif ch in (ord('k'),) or ch == 259:
            cur = app.views["log"].get("selection", 0) or 0
            app.views["log"]["selection"] = max(cur - 1, 0)
        elif ch == ord('g'):
            app.views["log"]["selection"] = 0
        elif ch == ord('G'):
            if app.messages:
                app.views["log"]["selection"] = len(app.messages) - 1

def _tui_text_view(holder, app):
    return 0

# ---------------------------------------------------------------------------

def main():
    argv = sys.argv
    try:
        sys.stdout.reconfigure(errors="surrogateescape")
    except Exception:
        pass
    try:
        sys.stderr.reconfigure(errors="surrogateescape")
    except Exception:
        pass
    if len(argv) > 1 and argv[1] == "-m":
        return run_mgmt(argv)
    try:
        return run_main(argv)
    except CliExit as e:
        return e.code
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        return 0

if __name__ == "__main__":
    sys.exit(main())
