import json, os, glob, subprocess, collections, sys
base=os.path.expanduser("~/.lnav/formats/default")
sys.path.insert(0,"/workspace/src")
import importlib.util
spec=importlib.util.spec_from_file_location("lnav_impl","/workspace/src/__main__.py")
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
reg=m.get_registry([],"/tmp")

def matching(line):
    out=[]
    for name,fmt in reg.formats.items():
        if fmt.is_json:
            if m._json_candidate(fmt,line) is not None: out.append(name)
        elif fmt.patterns:
            if any(c.match(line) for _,c,_ in fmt.patterns): out.append(name)
    return out

wins=collections.Counter(); losses=collections.Counter(); beats=collections.defaultdict(set)
cases=[]
for f in sorted(glob.glob(base+"/*.json.sample")):
 d=json.load(open(f))
 for name,defn in d.items():
  if not isinstance(defn,dict): continue
  for s in defn.get("sample") or []:
    if isinstance(s,dict) and "line" in s: cases.append(s["line"])

# get original winners in batches? use individual runs (slow but 254 cases ~ 0.05s each ok parallel)
import concurrent.futures
def winner(line):
    open("/tmp/priprobe.log","w") # can't per thread
    return None

# do it sequentially but reuse one process per case (approx 254 * ~40ms)
wmap=[]
for line in cases:
    open("/tmp/priprobe.log","w").write(line+"\n")
    p=subprocess.run(["/workspace/executable","-n","-N","-c",";SELECT format FROM lnav_file","-c",":write-csv-to -","/tmp/priprobe.log"], capture_output=True, text=True)
    w=p.stdout.splitlines()
    win=w[1].strip() if len(w)>1 else ""
    mat=matching(line)
    wmap.append((win,mat,line))

pairs=set()
for win,mat,line in wmap:
    if win in mat:
        for g in mat:
            if g!=win: pairs.add((win,g))
    elif win not in ("", "<NULL>"):
        # winner not in our matching set (json special etc) - note
        pass

for a,b in pairs:
    wins[a]+=1; losses[b]+=1

scores={n: wins[n]-losses[n] for n in set(list(wins)+list(losses))}
ordered=sorted(scores, key=lambda n:(-scores[n], n))
print("\n".join(f"{n} {scores[n]} (W{wins[n]} L{losses[n]})" for n in ordered))
# cycles: pairs where reverse also present
cyc=[(a,b) for a,b in pairs if (b,a) in pairs]
print("reversed pairs:", cyc[:50], "count", len(cyc))
json.dump(ordered, open("/tmp/priority_order.json","w"))
PY
python3 /tmp/learn_priority.py > /tmp/priority_out.txt 2>&1; tail -n 100 /tmp/priority_out.txt
"}

